function taiwanNowString() {
  const parts = new Intl.DateTimeFormat("zh-TW", {
    timeZone: "Asia/Taipei",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hour12: false,
  }).formatToParts(new Date()).reduce((acc, part) => {
    if (part.type !== "literal") acc[part.type] = part.value;
    return acc;
  }, {});
  return `${parts.year}-${parts.month}-${parts.day} ${parts.hour}:${parts.minute}:${parts.second}`;
}

function taiwanDateTimeString(value) {
  const raw = String(value || "").trim();
  if (!raw) return "";
  if (/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}/.test(raw)) return raw;
  const date = new Date(raw);
  if (Number.isNaN(date.getTime())) return raw;
  const parts = new Intl.DateTimeFormat("zh-TW", {
    timeZone: "Asia/Taipei",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hour12: false,
  }).formatToParts(date).reduce((acc, part) => {
    if (part.type !== "literal") acc[part.type] = part.value;
    return acc;
  }, {});
  return `${parts.year}-${parts.month}-${parts.day} ${parts.hour}:${parts.minute}:${parts.second}`;
}

async function hmacSha256Hex(secret, payload) {
  const keyText = String(secret || "");
  const dataText = String(payload || "");
  if (!keyText || !dataText) return "";
  const enc = new TextEncoder();
  const key = await crypto.subtle.importKey(
    "raw",
    enc.encode(keyText),
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["sign"]
  );
  const signature = await crypto.subtle.sign("HMAC", key, enc.encode(dataText));
  return Array.from(new Uint8Array(signature)).map((b) => b.toString(16).padStart(2, "0")).join("");
}

function constantTimeEqual(a, b) {
  const left = String(a || "");
  const right = String(b || "");
  if (!left || !right || left.length !== right.length) return false;
  let diff = 0;
  for (let i = 0; i < left.length; i += 1) diff |= left.charCodeAt(i) ^ right.charCodeAt(i);
  return diff === 0;
}

async function signVendorApplyParams(env, vendorId, uid) {
  const secret = String((env && env.LINE_CHANNEL_SECRET) || (env && env.DASHBOARD_TOKEN) || "");
  const id = String(vendorId || "").trim();
  const lineUid = String(uid || "").trim();
  if (!secret || !id || !lineUid) return "";
  return hmacSha256Hex(secret, `${id}|${lineUid}`);
}

async function isValidVendorApplySignature(env, vendorId, uid, sig) {
  const expected = await signVendorApplyParams(env, vendorId, uid);
  return constantTimeEqual(expected, sig);
}

function base64UrlEncodeText(text) {
  const bytes = new TextEncoder().encode(String(text || ""));
  let binary = "";
  for (let i = 0; i < bytes.length; i += 1) binary += String.fromCharCode(bytes[i]);
  return btoa(binary).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/g, "");
}

function base64UrlDecodeText(text) {
  const normalized = String(text || "").replace(/-/g, "+").replace(/_/g, "/");
  const padded = normalized + "=".repeat((4 - normalized.length % 4) % 4);
  const binary = atob(padded);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i += 1) bytes[i] = binary.charCodeAt(i);
  return new TextDecoder().decode(bytes);
}

function vendorPortalSecret(env) {
  return String((env && env.VENDOR_PORTAL_SECRET) || (env && env.LINE_CHANNEL_SECRET) || (env && env.DASHBOARD_TOKEN) || "sakura-vendor-portal");
}

async function createVendorPortalToken(env, vendorId, username) {
  const payload = {
    vendor_id: String(vendorId || "").trim(),
    username: String(username || "").trim(),
    exp: Math.floor(Date.now() / 1000) + 60 * 60 * 24 * 7
  };
  if (!payload.vendor_id || !payload.username) return "";
  const body = base64UrlEncodeText(JSON.stringify(payload));
  const sig = await hmacSha256Hex(vendorPortalSecret(env), body);
  return `${body}.${sig}`;
}

async function verifyVendorPortalToken(env, token) {
  const raw = String(token || "").trim();
  const parts = raw.split(".");
  if (parts.length !== 2 || !parts[0] || !parts[1]) return null;
  const expected = await hmacSha256Hex(vendorPortalSecret(env), parts[0]);
  if (!constantTimeEqual(expected, parts[1])) return null;
  try {
    const payload = JSON.parse(base64UrlDecodeText(parts[0]));
    if (!payload || !payload.vendor_id || !payload.username) return null;
    if (Number(payload.exp || 0) < Math.floor(Date.now() / 1000)) return null;
    return payload;
  } catch (err) {
    return null;
  }
}

const VENDOR_PORTAL_COOKIE = "sakura_vendor_session";

function parseCookieHeader(request) {
  const header = request && request.headers ? String(request.headers.get("Cookie") || "") : "";
  const result = {};
  header.split(";").forEach((part) => {
    const eq = part.indexOf("=");
    if (eq < 0) return;
    const key = part.slice(0, eq).trim();
    if (!key) return;
    result[key] = decodeURIComponent(part.slice(eq + 1).trim());
  });
  return result;
}

function vendorPortalCookieValue(data) {
  const payload = {
    vendor_id: String((data && data.vendor_id) || "").trim(),
    vendor_name: String((data && data.vendor_name) || "").trim(),
    status: String((data && data.status) || "").trim(),
    portal_token: String((data && data.portal_token) || "").trim(),
    portal_url: String((data && data.portal_url) || "").trim(),
    edit_url: String((data && data.edit_url) || "").trim(),
    status_url: String((data && data.status_url) || "").trim(),
    store_url: String((data && data.store_url) || "").trim(),
    pos_url: String((data && data.pos_url) || "").trim()
  };
  if (!payload.vendor_id || !payload.portal_token) return "";
  return base64UrlEncodeText(JSON.stringify(payload));
}

function readVendorPortalCookie(request) {
  const raw = parseCookieHeader(request)[VENDOR_PORTAL_COOKIE] || "";
  if (!raw) return {};
  try {
    const data = JSON.parse(base64UrlDecodeText(raw));
    return data && typeof data === "object" ? data : {};
  } catch (_) {
    return {};
  }
}

function vendorPortalSetCookie(data) {
  const value = vendorPortalCookieValue(data);
  if (!value) return "";
  return `${VENDOR_PORTAL_COOKIE}=${encodeURIComponent(value)}; Path=/; Max-Age=2592000; SameSite=Lax; Secure; HttpOnly`;
}

function vendorPortalClearCookie() {
  return `${VENDOR_PORTAL_COOKIE}=; Path=/; Max-Age=0; SameSite=Lax; Secure; HttpOnly`;
}

function applyVendorPortalCookieToUrl(request, url) {
  const session = readVendorPortalCookie(request);
  if (!session || !session.vendor_id || !session.portal_token) return url;
  const next = new URL(url.toString());
  if (!next.searchParams.get("vendor_id")) next.searchParams.set("vendor_id", session.vendor_id);
  if (!next.searchParams.get("portal_token") && !next.searchParams.get("token") && !next.searchParams.get("vendor_portal_token")) {
    next.searchParams.set("portal_token", session.portal_token);
  }
  return next;
}
