async function getClubDirectory(url) {
  const keyword = String(url.searchParams.get("keyword") || "").trim().toLowerCase();
  const type = String(url.searchParams.get("type") || "").trim();
  const category = String(url.searchParams.get("category") || "").trim();
  const status = String(url.searchParams.get("status") || "").trim();
  const allClubs = getDefaultClubRecords();
  const clubs = allClubs.filter((club) => { const hay = JSON.stringify(club).toLowerCase(); return (!keyword || hay.includes(keyword)) && (!type || club.type === type) && (!category || club.category === category) && (!status || club.status === status); });
  return { success: true, count: clubs.length, total: allClubs.length, clubs, events: getDefaultClubEvents(), galleries: getDefaultClubGallery() };
}

