async function saveLineKeywordRule(db, data) {
  await ensureLineKeywordTables(db);
  const keyword = String(data.keyword || "").trim();
  if (!keyword) return { success: false, message: "請填寫關鍵字。" };
  const id = String(data.id || "").trim() || crypto.randomUUID();
  const metadataJson = String(data.metadata_json || data.metadataJson || "{}").trim() || "{}";
  try {
    JSON.parse(metadataJson);
  } catch (err) {
    return { success: false, message: "進階設定 JSON 格式錯誤。" };
  }
  await db.prepare(`
    INSERT INTO line_keyword_rules (
      id, keyword, match_type, action_type, title, description, reply_text,
      target_url, flex_template_id, point_type, point_amount, requires_employee,
      vendor_required, cooldown_seconds, priority, active, metadata_json,
      created_at, updated_at
    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime('now'), datetime('now'))
    ON CONFLICT(id) DO UPDATE SET
      keyword = excluded.keyword,
      match_type = excluded.match_type,
      action_type = excluded.action_type,
      title = excluded.title,
      description = excluded.description,
      reply_text = excluded.reply_text,
      target_url = excluded.target_url,
      flex_template_id = excluded.flex_template_id,
      point_type = excluded.point_type,
      point_amount = excluded.point_amount,
      requires_employee = excluded.requires_employee,
      vendor_required = excluded.vendor_required,
      cooldown_seconds = excluded.cooldown_seconds,
      priority = excluded.priority,
      active = excluded.active,
      metadata_json = excluded.metadata_json,
      updated_at = datetime('now')
  `).bind(
    id,
    keyword,
    normalizeKeywordMatchType(data.match_type || data.matchType),
    normalizeKeywordActionType(data.action_type || data.actionType),
    String(data.title || keyword).trim(),
    String(data.description || "").trim(),
    String(data.reply_text || data.replyText || "").trim(),
    String(data.target_url || data.targetUrl || "").trim(),
    String(data.flex_template_id || data.flexTemplateId || "").trim(),
    String(data.point_type || data.pointType || "system_point").trim(),
    Number(data.point_amount || data.pointAmount || 0),
    Number(data.requires_employee || data.requiresEmployee || 0) ? 1 : 0,
    Number(data.vendor_required || data.vendorRequired || 0) ? 1 : 0,
    Math.max(Number(data.cooldown_seconds || data.cooldownSeconds || 0), 0),
    Number(data.priority || 100),
    Number(data.active) === 0 ? 0 : 1,
    metadataJson
  ).run();
  return { success: true, message: "關鍵字規則已儲存。", data: { id } };
}

async function deleteLineKeywordRule(db, data) {
  await ensureLineKeywordTables(db);
  const id = String(data.id || "").trim();
  if (!id) return { success: false, message: "缺少規則 id。" };
  await db.prepare("DELETE FROM line_keyword_rules WHERE id = ?").bind(id).run();
  return { success: true, message: "關鍵字規則已刪除。" };
}

