async function resolveLineRichMenuAlias(env, aliasId) {
  const normalized = normalizeRichMenuAliasId(aliasId);
  if (!normalized || !env || !env.LINE_CHANNEL_ACCESS_TOKEN) return { richMenuId: "", source: "line_alias_missing", aliasId: normalized };
  const cached = richMenuAliasCache.get(normalized);
  if (cached && cached.expiresAt > Date.now() && String(cached.richMenuId || "").startsWith("richmenu-")) {
    return { richMenuId: cached.richMenuId, source: "line_alias_cache", aliasId: normalized };
  }
  const result = await lineApi("https://api.line.me/v2/bot/richmenu/alias/" + encodeURIComponent(normalized), env, {
    method: "GET",
    body: undefined,
    contentType: "application/json",
  });
  const richMenuId = String(result.json && result.json.richMenuId || "").trim();
  if (result.ok && richMenuId.startsWith("richmenu-")) {
    richMenuAliasCache.set(normalized, { richMenuId, expiresAt: Date.now() + RICH_MENU_ALIAS_CACHE_TTL_MS });
    return { richMenuId, source: "line_alias", aliasId: normalized, status: result.status };
  }
  richMenuAliasCache.delete(normalized);
  return { richMenuId: "", source: "line_alias_not_found", aliasId: normalized, status: result.status, text: result.text };
}

async function resolveLineRichMenuAliasFresh(env, aliasId) {
  const normalized = normalizeRichMenuAliasId(aliasId);
  if (normalized) richMenuAliasCache.delete(normalized);
  return resolveLineRichMenuAlias(env, normalized);
}
async function resolveKeywordRichMenuId(db, env, rule) {
  const meta = parseJsonObject(rule && rule.metadata_json);
  const directId = String(meta.richMenuId || meta.rich_menu_id || rule.target_url || "").trim();
  if (directId.startsWith("richmenu-")) return { richMenuId: directId, source: "direct" };

  const projectId = String(meta.richMenuProjectId || meta.rich_menu_project_id || "").trim();
  const aliasId = normalizeRichMenuAliasId(meta.richMenuAliasId || meta.rich_menu_alias_id || "");
  const fallbackAliasId = !aliasId && directId && !directId.startsWith("richmenu-") ? normalizeRichMenuAliasId(directId) : "";
  if (!db && !aliasId && !fallbackAliasId) return { richMenuId: "", source: "missing" };

  try {
    if (db && (projectId || aliasId || fallbackAliasId)) {
      const rows = await db.prepare(`
        SELECT id, name, config_json, deployed_rich_menu_id
        FROM rich_menu_projects
        WHERE deployed_rich_menu_id <> ''
        ORDER BY
      CASE WHEN COALESCE(deployed_rich_menu_id, '') <> '' THEN 0 ELSE 1 END,
      updated_at DESC
        LIMIT 200
      `).all();
      for (const row of rows.results || []) {
        let config = {};
        try { config = JSON.parse(row.config_json || "{}"); } catch (err) { config = {}; }
        const rowAlias = normalizeRichMenuAliasId(config.aliasId || config.richMenuAliasId || "");
        if ((projectId && row.id === projectId) || (aliasId && rowAlias === aliasId) || (fallbackAliasId && rowAlias === fallbackAliasId)) {
          return { richMenuId: String(row.deployed_rich_menu_id || "").trim(), source: projectId ? "project" : "alias", projectId: row.id, aliasId: rowAlias };
        }
      }
    }
  } catch (err) {
    const lineResolved = aliasId ? await resolveLineRichMenuAlias(env, aliasId) : (fallbackAliasId ? await resolveLineRichMenuAlias(env, fallbackAliasId) : null);
    if (lineResolved && lineResolved.richMenuId) return { ...lineResolved, dbError: err && err.message ? err.message : String(err) };
    return { richMenuId: "", source: "error", error: err && err.message ? err.message : String(err), aliasId, fallbackAliasId };
  }

  if (aliasId) {
    const lineResolved = await resolveLineRichMenuAlias(env, aliasId);
    if (lineResolved.richMenuId) return lineResolved;
  }
  if (fallbackAliasId) {
    const lineResolved = await resolveLineRichMenuAlias(env, fallbackAliasId);
    if (lineResolved.richMenuId) return lineResolved;
  }
  return { richMenuId: "", source: "not_found", projectId, aliasId, fallbackAliasId };
}
async function resolveIdentityRichMenuForKeyword(db, env, lineUserId, rule) {
  const meta = parseJsonObject(rule && rule.metadata_json);
  const fallbackAliasId = normalizeRichMenuAliasId(meta.fallbackAliasId || meta.fallback_alias_id || "guest_zh");
  const fallback = async (identity, reason) => {
    const binding = db ? await selectRichMenuBindingForIdentity(db, identity) : null;
    const resolved = binding ? await resolveRichMenuIdForBinding(db, env, binding) : { richMenuId: "", source: "missing_binding" };
    if (resolved.richMenuId) {
      return { ...resolved, identity, bindingId: binding.id || "", bindingAliasId: binding.rich_menu_alias_id || "", reason };
    }
    const aliasResolved = fallbackAliasId ? await resolveLineRichMenuAlias(env, fallbackAliasId) : { richMenuId: "", source: "missing_fallback_alias" };
    return { ...aliasResolved, identity, bindingId: binding && binding.id || "", bindingAliasId: binding && binding.rich_menu_alias_id || fallbackAliasId, reason, fallbackAliasId };
  };

  const visitorIdentity = { targetType: "visitor", language: "zh-TW", bindStatus: "unbound", vendorStatus: "" };
  if (!db || !lineUserId) return fallback(visitorIdentity, "missing_db_or_line_user_id");

  try {
    const vendor = await db.prepare(`
      SELECT id, name, status, contact_line_user_id, submitted_by_line_user_id, updated_at
      FROM welfare_vendors
      WHERE contact_line_user_id = ? OR submitted_by_line_user_id = ?
      ORDER BY CASE WHEN status = 'approved' THEN 0 ELSE 1 END, updated_at DESC
      LIMIT 1
    `).bind(lineUserId, lineUserId).first();
    if (vendor && vendor.id) {
      const vendorStatus = normalizeVendorStatus(vendor.status) === "approved" ? "approved" : "pending";
      const identity = { targetType: "vendor", language: "zh-TW", bindStatus: "bound", vendorStatus };
      const resolved = await fallback(identity, "welfare_vendors");
      return { ...resolved, subjectId: vendor.id || "", subjectName: vendor.name || "" };
    }
  } catch (err) {
    // Older schema fallback: continue to member lookup if vendor LINE columns are unavailable.
  }

  try {
    const member = await db.prepare(`
      SELECT line_user_id, display_name, member_type, bind_status, language, employee_no, updated_at
      FROM welfare_members
      WHERE line_user_id = ?
      ORDER BY CASE WHEN bind_status = 'bound' THEN 0 ELSE 1 END, updated_at DESC
      LIMIT 1
    `).bind(lineUserId).first();
    if (member && (String(member.bind_status || "") === "bound" || String(member.employee_no || "").trim())) {
      const identity = {
        targetType: normalizeRichMenuTargetType(member.member_type || "employee"),
        language: normalizeEmployeeBindingLanguage(member.language || "zh-TW"),
        bindStatus: String(member.bind_status || "bound").trim() || "bound",
        vendorStatus: "",
      };
      const resolved = await fallback(identity, "welfare_members");
      return { ...resolved, subjectId: member.line_user_id || "", subjectName: member.display_name || "" };
    }
  } catch (err) {
    return fallback(visitorIdentity, "member_lookup_error");
  }

  return fallback(visitorIdentity, "visitor_fallback");
}
async function persistKeywordRichMenuId(db, rule, richMenuId) {
  if (!db || !rule || !rule.id || !String(richMenuId || "").startsWith("richmenu-")) return false;
  const meta = parseJsonObject(rule.metadata_json);
  if (String(meta.richMenuId || "").trim() === richMenuId) return false;
  meta.richMenuId = richMenuId;
  meta.flow = meta.flow || "rich_menu_link";
  try {
    await db.prepare(`
      UPDATE line_keyword_rules
      SET metadata_json = ?, updated_at = datetime('now', '+8 hours')
      WHERE id = ?
    `).bind(JSON.stringify(meta), rule.id).run();
    rule.metadata_json = JSON.stringify(meta);
    return true;
  } catch (err) {
    return false;
  }
}
async function applyKeywordRichMenuRule(db, env, item, rule) {
  const lineUserId = String(item && item.LINE_user_id || "").trim();
  const replyText = String(rule.reply_text || "正在切換圖文選單，若下方選單沒有立即更新，請重新開啟聊天室。").trim() || "正在切換圖文選單，若下方選單沒有立即更新，請重新開啟聊天室。";
  const meta = parseJsonObject(rule && rule.metadata_json);
  const identityFlow = String(meta.flow || "").trim() === "identity_rich_menu";
  const resolved = identityFlow ? await resolveIdentityRichMenuForKeyword(db, env, lineUserId, rule) : await resolveKeywordRichMenuId(db, env, rule);
  const richMenuId = resolved.richMenuId || "";
  let linkResult = { ok: false, status: 0, text: "missing richMenuId" };
  let messages = [];

  if (!lineUserId) {
    messages = [{ type: "text", text: "找不到這筆聊天室的 LINE 使用者 ID。" }];
  } else if (!richMenuId) {
    messages = [{ type: "text", text: "尚未設定可呼叫的 Rich Menu ID，請通知管理員。" }];
  } else if (!env.LINE_CHANNEL_ACCESS_TOKEN) {
    messages = [{ type: "text", text: "LINE Token 尚未設定，無法切換圖文選單。" }];
  } else {
    messages = [{ type: "text", text: replyText }];
  }

  const lineResult = item.replyToken ? await replyLineMessages(env, item.replyToken, messages) : { ok: false, status: 0, text: "missing replyToken" };
  let persistedRichMenuId = false;
  if (lineUserId && richMenuId && env.LINE_CHANNEL_ACCESS_TOKEN) {
    linkResult = await lineApi("https://api.line.me/v2/bot/user/" + encodeURIComponent(lineUserId) + "/richmenu/" + encodeURIComponent(richMenuId), env, {
      method: "POST",
      body: "",
      contentType: "application/json",
    });
    if (linkResult.ok && !identityFlow) persistedRichMenuId = await persistKeywordRichMenuId(db, rule, richMenuId);
  }

  await recordLineSystemOutboundMessage(db, {
    lineUserId,
    sourceGroupId: item.sourceGroupId,
    text: messages.map((m) => m.text || "").filter(Boolean).join("\n"),
    eventId: "keyword-rich-menu-" + (item.eventId || crypto.randomUUID()),
    rawJson: {
      source: "line-keyword-rich-menu",
      ruleId: rule.id || "",
      keyword: rule.keyword || "",
      actionType: "rich_menu_link",
      richMenuId,
      resolved,
      linkResult,
      lineResult,
      persistedRichMenuId,
      identityFlow,
    },
  });
  return {
    type: "line_keyword_rich_menu",
    ruleId: rule.id || "",
    keyword: rule.keyword || "",
    actionType: "rich_menu_link",
    richMenuId,
    ok: Boolean(lineResult.ok && richMenuId && linkResult.ok),
    status: linkResult.status || lineResult.status,
    linkResult,
    lineResult,
    persistedRichMenuId,
    resolved,
    identityFlow,
  };
}

async function maybeReplyLineKeywordRule(db, env, item, rule, origin) {
  if (!env || !item || !item.replyToken || !rule) return null;
  const keyword = String(rule.keyword || item.text || "").trim();
  if (isMotherOnlyLineKeyword(keyword) || String(rule.action_type || "").trim() === "mother_passthrough") {
    return {
      type: "line_keyword_passthrough",
      ruleId: rule.id || "",
      keyword,
      actionType: String(rule.action_type || "").trim() || "mother_passthrough",
      ok: true,
      status: "mother_passthrough",
    };
  }
  const actionType = String(rule.action_type || "").trim();
  if (actionType === "rich_menu_link") {
    return applyKeywordRichMenuRule(db, env, item, rule);
  }
  if (!["referral_link", "reply_text", "open_url"].includes(actionType)) return null;

  let messages = [];
  let replyText = String(rule.reply_text || "").trim();

  if (actionType === "referral_link") {
    const referralUrl = buildReferralShareUrl(env, rule, item);
    replyText = replyText || "這是您的專屬分享連結，好友完成加入或註冊後會登記在您的推薦名下。";
    messages = [buildReferralShareFlex(rule, item, referralUrl, replyText)];
  } else if (actionType === "open_url") {
    const targetUrl = buildKeywordTargetUrl(env, rule, item);
    replyText = replyText || "請點下方按鈕開啟連結。";
    messages = [{
      type: "flex",
      altText: String(rule.title || rule.keyword || "開啟連結").slice(0, 400),
      contents: {
        type: "bubble",
        size: "mega",
        body: {
          type: "box",
          layout: "vertical",
          spacing: "md",
          contents: [
            { type: "text", text: String(rule.title || rule.keyword || "開啟連結"), weight: "bold", size: "lg", wrap: true },
            { type: "text", text: replyText, size: "sm", color: "#64748b", wrap: true },
          ],
        },
        footer: {
          type: "box",
          layout: "vertical",
          contents: [{ type: "button", style: "primary", color: "#06c755", action: { type: "uri", label: "開啟", uri: targetUrl } }],
        },
      },
    }];
  } else {
    if (!replyText) return null;
    messages = [{ type: "text", text: replyText.slice(0, 5000) }];
  }

  const lineResult = await replyLineMessages(env, item.replyToken, messages);
  await recordLineSystemOutboundMessage(db, {
    lineUserId,
    sourceGroupId: item.sourceGroupId,
    text: replyText,
    eventId: "keyword-reply-" + (item.eventId || crypto.randomUUID()),
    rawJson: {
      source: "line-keyword-rule",
      ruleId: rule.id || "",
      keyword: rule.keyword || "",
      actionType,
      lineResult,
      persistedRichMenuId: false,
    },
  });

  return {
    type: "line_keyword_reply",
    ruleId: rule.id || "",
    keyword: rule.keyword || "",
    actionType,
    ok: lineResult.ok,
    status: lineResult.status,
  };
}

function parseJsonObject(value) {
  try {
    const parsed = JSON.parse(String(value || "{}"));
    return parsed && typeof parsed === "object" && !Array.isArray(parsed) ? parsed : {};
  } catch (err) {
    return {};
  }
}

function buildKeywordTargetUrl(env, rule, item) {
  const target = String(rule && rule.target_url ? rule.target_url : "/").trim() || "/";
  const uid = String(item && item.LINE_user_id ? item.LINE_user_id : "").trim();
  const url = target.startsWith("http://") || target.startsWith("https://")
    ? new URL(target)
    : new URL(buildLiffUrl(env, target));
  if (uid && !url.searchParams.get("uid")) url.searchParams.set("uid", uid);
  return url.toString();
}

function buildReferralShareUrl(env, rule, item) {
  const meta = parseJsonObject(rule && rule.metadata_json);
  const uid = String(item && item.LINE_user_id ? item.LINE_user_id : "").trim();
  const param = String(meta.referralParam || "ref").trim() || "ref";
  const target = String(rule && rule.target_url ? rule.target_url : "/referral").trim() || "/referral";
  const normalizedTarget = target === "/" || target.startsWith("https://liff.line.me/") ? "/referral" : target;
  const url = normalizedTarget.startsWith("http://") || normalizedTarget.startsWith("https://")
    ? new URL(normalizedTarget)
    : new URL(normalizedTarget, getPublicOrigin(env));
  if (uid) {
    url.searchParams.set(param, uid);
    url.searchParams.set("uid", uid);
  }
  url.searchParams.set("source", "member_share");
  return url.toString();
}

function buildReferralShareFlex(rule, item, referralUrl, replyText) {
  const title = String(rule && (rule.title || rule.keyword) ? (rule.title || rule.keyword) : "會員分享");
  const uid = String(item && item.LINE_user_id ? item.LINE_user_id : "");
  return {
    type: "flex",
    altText: title,
    contents: {
      type: "bubble",
      size: "mega",
      body: {
        type: "box",
        layout: "vertical",
        spacing: "md",
        contents: [
          { type: "text", text: title, weight: "bold", size: "xl", wrap: true, color: "#071226" },
          { type: "text", text: replyText, size: "sm", wrap: true, color: "#475569", margin: "sm" },
          {
            type: "box",
            layout: "vertical",
            margin: "md",
            paddingAll: "12px",
            backgroundColor: "#f8fafc",
            cornerRadius: "8px",
            contents: [
              { type: "text", text: "推薦碼", size: "xs", color: "#64748b", weight: "bold" },
              { type: "text", text: uid || "LINE_USER", size: "xs", color: "#334155", wrap: true, margin: "xs" },
            ],
          },
        ],
      },
      footer: {
        type: "box",
        layout: "vertical",
        spacing: "sm",
        contents: [
          { type: "button", style: "primary", color: "#06c755", action: { type: "uri", label: "開啟我的分享連結", uri: referralUrl } },
          { type: "button", style: "secondary", action: { type: "uri", label: "複製/轉傳給好友", uri: referralUrl } },
        ],
      },
    },
  };
}

async function getLineSegmentPushDashboard(db) {
  const crm = await getCrmUsersDashboard(db);
  const flex = await listFlexTemplates(db);
  const users = (crm.users || []).filter((user) => String(user.line_user_id || "").trim());
  const tagMap = new Map();
  for (const user of users) {
    for (const tag of uniqueCsv(user.tags)) {
      tagMap.set(tag, (tagMap.get(tag) || 0) + 1);
    }
  }
  const tags = Array.from(tagMap.entries())
    .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
    .map(([name, count]) => ({ name, count }));

  return {
    success: true,
    data: {
      summary: {
        totalUsers: users.length,
        pushableUsers: users.filter((user) => user.line_user_id).length,
        employees: users.filter((user) => user.member_type === "employee").length,
        visitors: users.filter((user) => user.member_type === "visitor").length,
        bound: users.filter((user) => user.bind_status === "bound" || user.employee_no).length,
      },
      tags: tags.map((tag) => tag.name),
      tagStats: tags,
      templates: flex.templates || [],
      users,
    },
  };
}

async function handleLineSegmentPush(request, db, env) {
  try {
  const body = await request.json();
  const action = String(body.action || "preview").trim();
  const title = String(body.title || "LINE 分眾推播").trim().slice(0, 120);
  const filters = body.filters && typeof body.filters === "object" ? body.filters : {};
  const messageInput = body.message && typeof body.message === "object" ? body.message : {};
  const dashboard = await getLineSegmentPushDashboard(db);
  let recipients = filterLineSegmentRecipients(dashboard.data.users || [], filters);
  const selected = Array.isArray(filters.selectedLineUserIds)
    ? new Set(filters.selectedLineUserIds.map((id) => String(id || "").trim()).filter(Boolean))
    : new Set();
  if (selected.size) recipients = recipients.filter((user) => selected.has(user.line_user_id));
  const maxRecipients = Math.min(Math.max(Number(filters.maxRecipients || 200), 1), 500);
  recipients = recipients.slice(0, maxRecipients);

  if (action === "preview") {
    return {
      success: true,
      message: "受眾預覽完成。",
      data: {
        title,
        recipientCount: recipients.length,
        recipients,
        filters,
      },
    };
  }

  if (action !== "send") return { success: false, message: "Unsupported segmented push action." };
  if (!env.LINE_CHANNEL_ACCESS_TOKEN) return { success: false, message: "LINE_CHANNEL_ACCESS_TOKEN is not configured." };
  if (!recipients.length) return { success: false, message: "沒有符合條件且已勾選的受眾。" };

  const messages = await buildSegmentPushMessages(db, messageInput);
  await ensureLineSegmentPushTables(db);
  const campaignId = crypto.randomUUID();
  await db.prepare(`
    INSERT INTO welfare_push_campaigns (
      id, title, message_mode, filters_json, message_json, recipient_count,
      success_count, failed_count, status, created_at, updated_at
    ) VALUES (?, ?, ?, ?, ?, ?, 0, 0, 'sending', datetime('now'), datetime('now'))
  `).bind(
    campaignId,
    title,
    String(messageInput.mode || "official_text"),
    JSON.stringify(filters),
    JSON.stringify(messages),
    recipients.length
  ).run();

  const results = [];
  let successCount = 0;
  let failedCount = 0;
  for (const user of recipients) {
    const result = await lineApi("https://api.line.me/v2/bot/message/push", env, {
      method: "POST",
      body: JSON.stringify({ to: user.line_user_id, messages }),
      contentType: "application/json",
    });
    const ok = Boolean(result.ok);
    if (ok) successCount += 1;
    else failedCount += 1;
    results.push({ lineUserId: user.line_user_id, ok, status: result.status, body: result.text });
    await db.prepare(`
      INSERT INTO welfare_push_deliveries (
        id, campaign_id, line_user_id, display_name, status, response_status, response_body, created_at
      ) VALUES (?, ?, ?, ?, ?, ?, ?, datetime('now'))
    `).bind(
      crypto.randomUUID(),
      campaignId,
      user.line_user_id,
      user.display_name || "",
      ok ? "sent" : "failed",
      result.status || 0,
      String(result.text || "").slice(0, 2000)
    ).run();
  }

  await db.prepare(`
    UPDATE welfare_push_campaigns
    SET success_count = ?, failed_count = ?, status = ?, updated_at = datetime('now')
    WHERE id = ?
  `).bind(successCount, failedCount, failedCount ? "partial" : "sent", campaignId).run();

  return {
    success: true,
    message: failedCount ? "分眾推播完成，但部分對象失敗。" : "分眾推播已送出。",
    data: {
      id: campaignId,
      title,
      recipientCount: recipients.length,
      successCount,
      failedCount,
      results,
    },
  };
  } catch (err) {
    return { success: false, message: err && err.message ? err.message : String(err) };
  }
}

function filterLineSegmentRecipients(users, filters) {
  const keyword = String(filters.keyword || "").trim().toLowerCase();
  const tags = Array.isArray(filters.tags) ? filters.tags.map((tag) => String(tag || "").trim()).filter(Boolean) : [];
  const tagMode = String(filters.tagMode || "any") === "all" ? "all" : "any";
  const memberType = String(filters.memberType || "").trim();
  const bindStatus = String(filters.bindStatus || "").trim();

  return (users || []).filter((user) => {
    if (!String(user.line_user_id || "").trim()) return false;
    if (keyword) {
      const haystack = [
        user.display_name, user.line_user_id, user.employee_no, user.phone, user.email,
        user.language, user.tags, user.last_message,
      ].join(" ").toLowerCase();
      if (!haystack.includes(keyword)) return false;
    }
    if (memberType && String(user.member_type || "unknown") !== memberType) return false;
    if (bindStatus) {
      const isBound = user.bind_status === "bound" || Boolean(user.employee_no);
      if (bindStatus === "bound" && !isBound) return false;
      if (bindStatus === "unbound" && isBound) return false;
    }
    if (tags.length) {
      const userTags = uniqueCsv(user.tags);
      const matched = tagMode === "all"
        ? tags.every((tag) => userTags.includes(tag))
        : tags.some((tag) => userTags.includes(tag));
      if (!matched) return false;
    }
    return true;
  });
}

async function buildSegmentPushMessages(db, input) {
  const mode = String(input.mode || "official_text");
  if (mode === "official_text") {
    const text = String(input.text || "").trim();
    if (!text) throw new Error("文字內容必填。");
    return [{ type: "text", text: text.slice(0, 5000) }];
  }
  if (mode === "official_image") {
    const originalContentUrl = String(input.originalContentUrl || "").trim();
    const previewImageUrl = String(input.previewImageUrl || originalContentUrl).trim();
    if (!isHttpUrl(originalContentUrl) || !isHttpUrl(previewImageUrl)) throw new Error("圖片推播必須提供 https 圖片 URL。");
    return [{ type: "image", originalContentUrl, previewImageUrl }];
  }
  if (mode === "system_template") {
    const id = String(input.templateId || "").trim();
    if (!id) throw new Error("請選擇 Flex 版型。");
    const row = await db.prepare(`
      SELECT id, name, reply_type, payload_json
      FROM welfare_flex_templates
      WHERE id = ? AND (category IS NULL OR category <> 'share_draft')
      LIMIT 1
    `).bind(id).first();
    if (!row) throw new Error("找不到指定的 Flex 版型。");
    const replyType = String(row.reply_type || "FLEX").toUpperCase();
    const payload = parseJsonSafe(row.payload_json, {});
    if (replyType === "TEXT") {
      return [{ type: "text", text: String(payload.text || payload || row.name || "櫻花福委會訊息").slice(0, 5000) }];
    }
    return [{ type: "flex", altText: String(input.altText || row.name || "櫻花福委會訊息").slice(0, 400), contents: payload }];
  }
  if (mode === "system_json") {
    const contents = input.contents;
    if (!contents || typeof contents !== "object" || !contents.type) throw new Error("Flex JSON 必須是 LINE Flex contents 物件。");
    return [{ type: "flex", altText: String(input.altText || "櫻花福委會訊息").slice(0, 400), contents }];
  }
  throw new Error("不支援的推播內容格式。");
}

function isHttpUrl(value) {
  try {
    const url = new URL(String(value || ""));
    return url.protocol === "https:" || url.protocol === "http:";
  } catch (err) {
    return false;
  }
}

async function ensureLineSegmentPushTables(db) {
  await db.prepare(`
    CREATE TABLE IF NOT EXISTS welfare_push_campaigns (
      id TEXT PRIMARY KEY,
      title TEXT NOT NULL DEFAULT '',
      message_mode TEXT NOT NULL DEFAULT '',
      filters_json TEXT NOT NULL DEFAULT '{}',
      message_json TEXT NOT NULL DEFAULT '[]',
      recipient_count INTEGER NOT NULL DEFAULT 0,
      success_count INTEGER NOT NULL DEFAULT 0,
      failed_count INTEGER NOT NULL DEFAULT 0,
      status TEXT NOT NULL DEFAULT 'draft',
      created_at TEXT NOT NULL DEFAULT (datetime('now')),
      updated_at TEXT NOT NULL DEFAULT (datetime('now'))
    )
  `).run();
  await db.prepare(`
    CREATE TABLE IF NOT EXISTS welfare_push_deliveries (
      id TEXT PRIMARY KEY,
      campaign_id TEXT NOT NULL,
      line_user_id TEXT NOT NULL DEFAULT '',
      display_name TEXT NOT NULL DEFAULT '',
      status TEXT NOT NULL DEFAULT '',
      response_status INTEGER NOT NULL DEFAULT 0,
      response_body TEXT NOT NULL DEFAULT '',
      created_at TEXT NOT NULL DEFAULT (datetime('now'))
    )
  `).run();
  await db.prepare(`
    CREATE INDEX IF NOT EXISTS idx_welfare_push_deliveries_campaign
    ON welfare_push_deliveries(campaign_id)
  `).run();
}

async function pushLineMonitorMessage(request, db, env) {
  const body = await request.json();
  const lineUserId = String(body.lineUserId || "").trim();
  const text = String(body.text || "").trim();
  if (!lineUserId || !text) return { success: false, message: "lineUserId and text are required." };
  const eventId = "admin-" + Date.now() + "-" + crypto.randomUUID();
  const createdAt = new Date().toISOString();
  let lineResult = { skipped: true, reason: "LINE_CHANNEL_ACCESS_TOKEN is not configured." };
  if (env.LINE_CHANNEL_ACCESS_TOKEN) {
    const response = await fetch("https://api.line.me/v2/bot/message/push", {
      method: "POST",
      headers: { Authorization: "Bearer " + env.LINE_CHANNEL_ACCESS_TOKEN, "Content-Type": "application/json" },
      body: JSON.stringify({ to: lineUserId, messages: [{ type: "text", text }] })
    });
    lineResult = { ok: response.ok, status: response.status, body: await response.text() };
  }
  await db.prepare(`
    INSERT INTO line_webhook_events (
      event_id, event_type, source_type, line_user_id, message_type, message_text,
      raw_payload, sentiment_type, priority, tags_json, suggested_action, process_status,
      ai_summary, ai_severity, ai_reason, ai_reply_suggestion, ai_analysis_json
    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
  `).bind(
    eventId, "admin_push", "admin", lineUserId, "text", text,
    JSON.stringify({ source: "line-oa-monitor", lineResult }), "admin_reply", "low",
    JSON.stringify(["管理員回覆"]), "line_push", lineResult.ok === false ? "open" : "archived",
    "管理員已回覆", "low", lineResult.ok === false ? "LINE Push API failed." : "Sent from monitor.", "", JSON.stringify(lineResult)
  ).run();

  if (lineResult.ok) {
    await recordLineMonitorOutboundMessage(db, {
      lineUserId,
      text,
      eventId,
      createdAt,
      lineResult,
    });
  }

  return { success: lineResult.skipped ? false : Boolean(lineResult.ok), message: lineResult.ok ? "已送出 LINE 訊息" : "無法送出 LINE Push API 訊息", lineResult };
}

async function recordLineMonitorOutboundMessage(db, data) {
  const lineUserId = String(data.lineUserId || "").trim();
  if (!db || !lineUserId) return;
  const threadId = "user:" + lineUserId;
  const text = String(data.text || "").trim();
  const createdAt = data.createdAt || new Date().toISOString();
  const eventId = data.eventId || "admin-" + Date.now() + "-" + crypto.randomUUID();
  const rawJson = JSON.stringify({ source: "line-oa-monitor", direction: "outbound", lineResult: data.lineResult || {} });

  await db.prepare(`
    INSERT INTO line_threads (
      id, source_type, source_user_id, source_group_id, display_name, picture_url, status,
      risk_level, summary, unread_count, tags, last_message_at, created_at, updated_at
    ) VALUES (?, 'line_oa', ?, '', ?, '', 'open', 'low', ?, 0, 'admin_reply', ?, ?, ?)
    ON CONFLICT(id) DO UPDATE SET
      summary = excluded.summary,
      unread_count = 0,
      last_message_at = excluded.last_message_at,
      updated_at = excluded.updated_at
  `).bind(
    threadId,
    lineUserId,
    "LINE " + lineUserId.slice(-6),
    text,
    createdAt,
    createdAt,
    createdAt
  ).run();

  await db.prepare(`
    INSERT OR IGNORE INTO line_messages (
      id, thread_id, line_event_id, reply_token, message_type, sender_role,
      sender_id, sender_name, message_text, raw_json, created_at
    ) VALUES (?, ?, ?, '', 'text', 'guide', 'admin', '管理員', ?, ?, ?)
  `).bind(
    crypto.randomUUID(),
    threadId,
    eventId,
    text,
    rawJson,
    createdAt
  ).run();
}

function normalizeLineProfileId(value) {
  const raw = String(value || "").trim();
  if (raw.startsWith("user:")) return raw.slice(5);
  return raw;
}

async function debugLineProfile(url, db, env) {
  const lineUserId = normalizeLineProfileId(url.searchParams.get("id") || url.searchParams.get("lineUserId"));
  if (!lineUserId) return { success: false, message: "Missing id or lineUserId." };

  const cached = await getCachedLineProfile(db, lineUserId);
  const direct = await fetchLineUserProfileDebug(lineUserId, env);
  const placeholderDetected = !cached || !cached.display_name || cached.display_name.startsWith("缺件踝? ");

  return {
    success: true,
    id: "user:" + lineUserId,
    thread: {
      source_user_id: lineUserId,
      display_name: cached ? cached.display_name : "",
      picture_url: cached ? cached.picture_url : "",
      updated_at: cached ? cached.updated_at : "",
    },
    placeholderDetected,
    profileChecks: {
      direct,
    },
  };
}

async function backfillLineProfiles(url, db, env) {
  const limit = Math.min(Math.max(Number(url.searchParams.get("limit") || 100), 1), 200);
  let rows;
  try {
    rows = await db.prepare(`
      SELECT DISTINCT source_user_id AS line_user_id
      FROM line_threads
      WHERE source_user_id IS NOT NULL
        AND source_user_id != ''
      ORDER BY
      CASE
        WHEN status = 'approved' THEN 0
        WHEN status = 'pending' THEN 1
        ELSE 2
      END,
      updated_at DESC
      LIMIT ?
    `).bind(limit).all();
  } catch (err) {
    rows = await db.prepare(`
      SELECT DISTINCT e.line_user_id
      FROM line_webhook_events e
      LEFT JOIN line_user_profiles p ON p.line_user_id = e.line_user_id
      WHERE e.line_user_id IS NOT NULL
        AND e.line_user_id != ''
        AND (p.line_user_id IS NULL OR p.display_name IS NULL OR p.display_name = '')
      ORDER BY e.id DESC
      LIMIT ?
    `).bind(limit).all();
  }

  const results = [];
  for (const row of rows.results || []) {
    const profile = await fetchLineUserProfileDebug(row.line_user_id, env);
    if (profile.status === 200 && profile.data) {
      await storeLineUserProfile(db, {
        LINE_user_id: row.line_user_id,
        lineDisplayName: profile.data.displayName || "",
        linePictureUrl: profile.data.pictureUrl || "",
        lineStatusMessage: profile.data.statusMessage || "",
      });
      try {
        await db.prepare(`
          UPDATE line_threads
          SET display_name = ?, picture_url = ?, updated_at = datetime('now')
          WHERE source_user_id = ?
        `).bind(
          profile.data.displayName || "",
          profile.data.pictureUrl || "",
          row.line_user_id
        ).run();
      } catch (err) {
        // Legacy deployments may not have line_threads yet.
      }
    }
    results.push({
      lineUserId: row.line_user_id,
      status: profile.status,
      displayName: profile.data ? profile.data.displayName : "",
      pictureUrl: profile.data ? profile.data.pictureUrl : "",
    });
  }

  return {
    success: true,
    checked: results.length,
    updated: results.filter((item) => item.status === 200 && item.displayName).length,
    results,
  };
}

async function getCachedLineProfile(db, lineUserId) {
  try {
    return await db.prepare(`
      SELECT line_user_id, display_name, picture_url, status_message, updated_at
      FROM line_user_profiles
      WHERE line_user_id = ?
    `).bind(lineUserId).first();
  } catch (err) {
    return null;
  }
}

async function fetchLineUserProfileDebug(lineUserId, env) {
  if (!env.LINE_CHANNEL_ACCESS_TOKEN) {
    return { status: 0, ok: false, error: "LINE_CHANNEL_ACCESS_TOKEN is not configured." };
  }

  try {
    const response = await fetch("https://api.line.me/v2/bot/profile/" + encodeURIComponent(lineUserId), {
      headers: {
        Authorization: "Bearer " + env.LINE_CHANNEL_ACCESS_TOKEN,
      },
    });
    const text = await response.text();
    let data = null;
    try {
      data = text ? JSON.parse(text) : null;
    } catch (err) {
      data = { raw: text };
    }
    return { status: response.status, ok: response.ok, data };
  } catch (err) {
    return { status: 0, ok: false, error: err.message };
  }
}

async function getLineEventDashboard(db, env) {
  const summary = await db.prepare(`
    SELECT
      COUNT(*) AS total,
      SUM(CASE WHEN process_status = 'open' THEN 1 ELSE 0 END) AS open_count,
      SUM(CASE WHEN priority = 'high' THEN 1 ELSE 0 END) AS high_count,
      SUM(CASE WHEN sentiment_type = 'complaint' THEN 1 ELSE 0 END) AS complaint_count,
      SUM(CASE WHEN sentiment_type = 'praise' THEN 1 ELSE 0 END) AS praise_count,
      SUM(CASE WHEN sentiment_type = 'vendor_support' THEN 1 ELSE 0 END) AS vendor_support_count
    FROM line_webhook_events
  `).first();

  let latest;
  try {
    latest = await db.prepare(`
      SELECT
        e.id,
        e.event_type,
        e.source_type,
        e.line_user_id,
        e.message_type,
        e.message_text,
        e.sentiment_type,
        e.priority,
        e.tags_json,
        e.suggested_action,
        e.process_status,
        e.ai_summary,
        e.ai_severity,
        e.ai_reason,
        e.ai_reply_suggestion,
        e.created_at,
        p.display_name,
        p.picture_url
      FROM line_webhook_events e
      LEFT JOIN line_user_profiles p ON p.line_user_id = e.line_user_id
      WHERE COALESCE(e.message_type, '') <> 'location'
      ORDER BY e.id DESC
      LIMIT 20
    `).all();
  } catch (err) {
    latest = await db.prepare(`
      SELECT
        id,
        event_type,
        source_type,
        line_user_id,
        message_type,
        message_text,
        sentiment_type,
        priority,
        tags_json,
        suggested_action,
        process_status,
        created_at
      FROM line_webhook_events
      WHERE COALESCE(message_type, '') <> 'location'
      ORDER BY id DESC
      LIMIT 20
    `).all();
  }

  const rowsWithProfiles = [];
  for (const row of latest.results || []) {
    if ((!row.display_name || !row.picture_url) && row.line_user_id) {
      const profile = await fetchLineUserProfile(row.line_user_id, env || {});
      if (profile) {
        row.display_name = profile.displayName || row.display_name;
        row.picture_url = profile.pictureUrl || row.picture_url;
        await storeLineUserProfile(db, {
          LINE_user_id: row.line_user_id,
          lineDisplayName: profile.displayName || "",
          linePictureUrl: profile.pictureUrl || "",
          lineStatusMessage: profile.statusMessage || "",
        });
      }
    }
    rowsWithProfiles.push(row);
  }

  let latestIntake = null;
  try {
    latestIntake = await db.prepare(`
      SELECT id, route, event_count, first_event_type, first_source_type, first_line_user_id,
             first_message_type, first_message_text, signature_present, signature_valid,
             stage, note, error, created_at
      FROM line_webhook_intake_logs
      ORDER BY id DESC
      LIMIT 1
    `).first();
  } catch (err) {
    latestIntake = { error: err && err.message ? err.message : String(err) };
  }

  return {
    success: true,
    diagnostics: {
      latestIntake,
    },
    summary: {
      total: Number(summary.total || 0),
      open: Number(summary.open_count || 0),
      high: Number(summary.high_count || 0),
      complaints: Number(summary.complaint_count || 0),
      praise: Number(summary.praise_count || 0),
      vendorSupport: Number(summary.vendor_support_count || 0),
    },
    events: rowsWithProfiles.map((row) => ({
      id: row.id,
      eventType: row.event_type,
      sourceType: row.source_type,
      lineUserId: row.line_user_id,
      displayName: row.display_name,
      pictureUrl: row.picture_url,
      messageType: row.message_type,
      messageText: formatLineDashboardMessage(row),
      rawMessageText: row.message_text,
      sentimentType: row.sentiment_type,
      priority: row.priority,
      tags: parseJsonArray(row.tags_json),
      suggestedAction: row.suggested_action,
      processStatus: row.process_status,
      aiSummary: row.ai_summary,
      aiSeverity: row.ai_severity,
      aiReason: row.ai_reason,
      aiReplySuggestion: row.ai_reply_suggestion,
      createdAt: row.created_at,
    })),
  };
}

function formatLineDashboardMessage(row) {
  const messageType = String(row && row.message_type || "");
  const text = String(row && row.message_text || "").trim();
  if (messageType === "location") {
    const area = extractTaiwanAreaFromLocationText(text);
    return area
      ? `使用者分享定位：${area}，已觸發附近店家查詢`
      : "使用者分享定位，已觸發附近店家查詢";
  }
  if (messageType && messageType !== "text") {
    const label = {
      image: "使用者傳送圖片",
      video: "使用者傳送影片",
      audio: "使用者傳送語音",
      file: "使用者傳送檔案",
      sticker: "使用者傳送貼圖",
    }[messageType];
    return label || `使用者傳送 ${messageType} 訊息`;
  }
  return text;
}

function extractTaiwanAreaFromLocationText(text) {
  const value = String(text || "");
  const cityMatch = value.match(/(?:台灣|臺灣)?([^0-9\s,，]{2,3}[縣市])([^0-9\s,，]{1,6}[區鄉鎮市])?/);
  if (cityMatch) return [cityMatch[1], cityMatch[2]].filter(Boolean).join("");
  const englishMatch = value.match(/\b(Taiwan)\s+([A-Za-z]+)\s+([A-Za-z]+)/i);
  if (englishMatch) return [englishMatch[2], englishMatch[3]].join(" ");
  return "";
}

function parseJsonArray(value) {
  try {
    const parsed = JSON.parse(value || "[]");
    return Array.isArray(parsed) ? parsed : [];
  } catch (err) {
    return [];
  }
}

async function forwardLineWebhook(targetUrl, rawBody, signature, targetType) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort("Webhook forward timeout"), 7000);
  try {
    const response = await fetch(targetUrl, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "x-line-signature": signature,
        "x-sakura-webhook-gateway": "cloudflare-worker",
        "x-sakura-webhook-target": targetType,
      },
      body: rawBody,
      signal: controller.signal,
    });

    return {
      ok: response.ok,
      status: response.status,
      body: response.ok ? "" : (await response.text()).slice(0, 500),
    };
  } catch (err) {
    return {
      ok: false,
      status: 0,
      error: err && err.message ? err.message : String(err),
    };
  } finally {
    clearTimeout(timer);
  }
}

async function verifyLineSignature(rawBody, signature, channelSecret) {
  if (!signature || !channelSecret) return false;

  const encoder = new TextEncoder();
  const key = await crypto.subtle.importKey(
    "raw",
    encoder.encode(channelSecret),
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["sign"]
  );
  const digest = await crypto.subtle.sign("HMAC", key, encoder.encode(rawBody));
  const expected = arrayBufferToBase64(digest);
  return timingSafeEqual(expected, signature);
}

function arrayBufferToBase64(buffer) {
  let binary = "";
  const bytes = new Uint8Array(buffer);
  for (let i = 0; i < bytes.byteLength; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

function timingSafeEqual(a, b) {
  if (a.length !== b.length) return false;
  let result = 0;
  for (let i = 0; i < a.length; i++) {
    result |= a.charCodeAt(i) ^ b.charCodeAt(i);
  }
  return result === 0;
}

async function moveUploadsToR2(data, bucket, origin) {
  const timestamp = Date.now();

  const transcriptFiles = [];
  if (data.transcriptFirstFile) transcriptFiles.push({ semester: "first", file: data.transcriptFirstFile });
  if (data.transcriptSecondFile) transcriptFiles.push({ semester: "second", file: data.transcriptSecondFile });
  if (Array.isArray(data.transcriptFiles)) {
    data.transcriptFiles.forEach((file, index) => transcriptFiles.push({ semester: "other_" + (index + 1), file }));
  }
  if (data.transcriptFile) transcriptFiles.push({ semester: "legacy", file: data.transcriptFile });

  const transcriptUrls = [];
  for (const item of transcriptFiles) {
    if (!item.file || !item.file.base64) continue;
    const stored = await storeBase64File(bucket, origin, "transcript_" + item.semester + "_" + timestamp, item.file);
    transcriptUrls.push({
      semester: item.semester,
      name: item.file.name,
      mimeType: item.file.mimeType,
      url: stored.url,
    });
  }

  if (transcriptUrls.length > 0) {
    data.transcriptUrls = transcriptUrls;
    data.transcriptUrl = transcriptUrls.map(item => item.url).join("\n");
  }

  if (data.photoFile && data.photoFile.base64) {
    const stored = await storeBase64File(bucket, origin, "photo_" + timestamp, data.photoFile);
    data.photoUrl = stored.url;
  }

  delete data.transcriptFirstFile;
  delete data.transcriptSecondFile;
  delete data.transcriptFiles;
  delete data.transcriptFile;
  delete data.photoFile;
}

async function storeBase64File(bucket, origin, prefix, fileData) {
  const safeName = sanitizeFileName(fileData.name || "upload");
  const fileName = prefix + "_" + safeName;
  const rawBase64 = String(fileData.base64 || "");
  const pureBase64 = rawBase64.includes(",") ? rawBase64.split(",").pop() : rawBase64;
  const binary = Uint8Array.from(atob(pureBase64), c => c.charCodeAt(0));
  await bucket.put(fileName, binary, {
    httpMetadata: {
      contentType: fileData.mimeType || "application/octet-stream",
    },
  });
  return {
    key: fileName,
    url: origin + "/file/" + encodeURIComponent(fileName),
  };
}

async function storeBinaryFile(bucket, origin, prefix, originalName, bytes, contentType) {
  const safeName = sanitizeFileName(originalName || "upload");
  const fileName = prefix + "_" + safeName;
  await bucket.put(fileName, bytes, {
    httpMetadata: {
      contentType: contentType || "application/octet-stream",
    },
  });
  return {
    key: fileName,
    url: origin + "/file/" + encodeURIComponent(fileName),
  };
}

function sanitizeFileName(name) {
  return name.replace(/[\\/:*?"<>|#%{}^~[\]`]/g, "_").replace(/\s+/g, "_").slice(0, 120);
}

const RICH_MENU_DEFAULT_HOME_SETTING_KEY = "rich_menu_default_home_project_id";
const VISITOR_DEFAULT_RICH_MENU_ALIAS_ID = "guest_zh";

function getRichMenuProjectAlias(config = {}) {
  return String(config.aliasId || config.richMenuAliasId || config.alias_id || "").trim();
}

function isVisitorDefaultRichMenuAlias(aliasId) {
  return String(aliasId || "").trim() === VISITOR_DEFAULT_RICH_MENU_ALIAS_ID;
}

function richMenuDefaultHomeGuardMessage(aliasId) {
  return `只有 alias ID 為 ${VISITOR_DEFAULT_RICH_MENU_ALIAS_ID} 的專案可設定為訪客預設首頁；目前 alias 是 ${aliasId || "未設定"}。twmem-menu / indo-menu / taimem-menu 是員工綁定選單，請從「Rich Menu 身分綁定」套用。`;
}

async function getDefaultHomeRichMenuProjectId(db) {
  if (!db) return "";
  const settings = await getSystemSettingsMap(db);
  return String(settings[RICH_MENU_DEFAULT_HOME_SETTING_KEY] || "").trim();
}

async function handleApi(action, data, db, env, request) {
  if (action === "RICH_MENU_LIST") return listRichMenuProjects(db);
  if (action === "RICH_MENU_LOAD") return loadRichMenuProject(db, data);
  if (action === "RICH_MENU_SAVE") return saveRichMenuProject(db, env, request, data);
  if (action === "RICH_MENU_DELETE") return deleteRichMenuProject(db, data);
  if (action === "RICH_MENU_SET_DEFAULT_HOME") return setDefaultHomeRichMenuProject(db, env, data);
  if (action === "RICH_MENU_SWITCH_DIAGNOSE") return runRichMenuSwitchDiagnose(db, env, data);
  if (action === "RICH_MENU_SWITCH_CHECKS") return listRichMenuSwitchChecks(db, data);
  if (action === "DEPLOY_RICH_MENU") return deployAndSaveRichMenu(data, db, env, request);
  if (action === "WELFARE_MEMBER_VERIFY") return verifyWelfareMember(db, env, data);
  if (action === "WELFARE_REDEMPTION_CREATE") return createWelfareRedemption(db, env, data);
  if (action === "WELFARE_AI_ASK") return answerWelfareInquiry(db, env, data);
  if (action === "WELFARE_KNOWLEDGE_SAVE") return saveKnowledgeAsset(db, env, data);
  if (action === "WELFARE_POINTS_QUERY") return queryMotherPointList(env, data);
  if (action === "WELFARE_POINTS_INSERT") return insertMotherPoint(env, data);
  if (action === "WELFARE_OFFER_DRAFT") return draftOfferFromOcr(db, env, data);
  if (action === "login") return loginAdmin(data, db, request);
  if (action === "submit") return submitApplication(data, db);
  if (action === "check") return checkApplication(data, db);
  if (action === "getAll") return getAllApplications(data, db, env);
  if (action === "updateStatus") return updateApplicationStatus(data, db, env);
  if (action === "delete") return deleteApplication(data, db, env);
  if (action === "getActivityLogs") return getActivityLogs(data, db, env);
  if (action === "logActivity") return logActivityFromClient(data, db, env);
  if (action === "getPermissionConfig") return getPermissionConfig(data, db, env);
  if (action === "savePermissionUser") return savePermissionUser(data, db, env);
  if (action === "reviewerRegister") return reviewerRegister(data, db);
  if (action === "reviewerLineLogin") return reviewerLineLogin(data, db, request);
  return { success: false, message: "缺件堊缺件?action: " + action };
}

async function listRichMenuProjects(db) {
  if (!db) return { success: false, message: "D1 binding DB is not configured." };
  const defaultHomeProjectId = await getDefaultHomeRichMenuProjectId(db);
  const rows = await db.prepare(`
    SELECT id, name, chat_bar_text, config_json, image_url, owner_uid, updated_at, deployed_rich_menu_id, deployed_at
    FROM rich_menu_projects
    ORDER BY
      CASE WHEN COALESCE(deployed_rich_menu_id, '') <> '' THEN 0 ELSE 1 END,
      updated_at DESC
    LIMIT 100
  `).all();
  const data = (rows.results || []).map((row) => {
    let config = {};
    try { config = JSON.parse(row.config_json || "{}"); } catch (err) { config = {}; }
    const areas = Array.isArray(config.areas) ? config.areas : [];
    const aliasId = getRichMenuProjectAlias(config);
    const canBeDefaultHome = isVisitorDefaultRichMenuAlias(aliasId);
    const legacyDefaultFlag = config.isDefaultHome === true || config.defaultHome === true;
    return {
      id: row.id || "",
      name: row.name || "未命名圖文選單",
      chatBarText: row.chat_bar_text || "選單",
      aliasId,
      canBeDefaultHome,
      defaultHomeMismatch: row.id === defaultHomeProjectId && !canBeDefaultHome,
      isDefaultHome: canBeDefaultHome && (row.id === defaultHomeProjectId || (!defaultHomeProjectId && legacyDefaultFlag)),
      areaCount: areas.length,
      imageUrl: row.image_url || "",
      ownerUid: row.owner_uid || "",
      deployedRichMenuId: row.deployed_rich_menu_id || "",
      deployedAt: row.deployed_at || "",
      updatedAt: row.updated_at || "",
    };
  });
  return { success: true, data };
}
async function loadRichMenuProject(db, data) {
  if (!db) return { success: false, message: "D1 binding DB is not configured." };
  const defaultHomeProjectId = await getDefaultHomeRichMenuProjectId(db);
  const id = String(data.id || "").trim();
  if (!id) return { success: false, message: "缺少 Rich Menu 專案 id。" };
  const row = await db.prepare(`
    SELECT *
    FROM rich_menu_projects
    WHERE id = ?
  `).bind(id).first();
  if (!row) return { success: false, message: "找不到 Rich Menu 專案。" };
  let config = {};
  try {
    config = JSON.parse(row.config_json || "{}");
  } catch (err) {
    config = {};
  }
  const areas = Array.isArray(config.areas) ? config.areas : [];
  const aliasId = getRichMenuProjectAlias(config);
  const canBeDefaultHome = isVisitorDefaultRichMenuAlias(aliasId);
  const legacyDefaultFlag = config.isDefaultHome === true || config.defaultHome === true;
  return {
    success: true,
    data: {
      ...row,
      id: row.id || "",
      name: row.name || config.name || "未命名圖文選單",
      chatBarText: row.chat_bar_text || config.chatBarText || "選單",
      aliasId,
      canBeDefaultHome,
      defaultHomeMismatch: row.id === defaultHomeProjectId && !canBeDefaultHome,
      isDefaultHome: canBeDefaultHome && (row.id === defaultHomeProjectId || (!defaultHomeProjectId && legacyDefaultFlag)),
      imageUrl: row.image_url || "",
      deployedRichMenuId: row.deployed_rich_menu_id || "",
      deployedAt: row.deployed_at || "",
      updatedAt: row.updated_at || "",
      config,
      areas,
    },
  };
}
function guardReservedRichMenuProjectAlias(projectId, aliasId) {
  const id = String(projectId || "").trim();
  const alias = String(aliasId || "").trim();
  const reserved = new Set(["twmem-menu", "indo-menu", "taimem-menu"]);
  if (!alias || !reserved.has(alias)) return { ok: true, id, aliasId: alias };
  if (id && reserved.has(id) && id !== alias) {
    return { ok: false, message: `語系選單不可交叉儲存：專案 ${id} 必須搭配同名 Alias ID，不能改成 ${alias}。` };
  }
  if (id && id !== alias) {
    return { ok: false, message: `語系選單 Alias ID ${alias} 必須儲存在同名專案；請從檔案庫開啟 ${alias}，或另存同名專案。` };
  }
  return { ok: true, id: alias || id, aliasId: alias };
}

async function saveRichMenuProject(db, env, request, data) {
  if (!db) return { success: false, message: "D1 binding DB is not configured." };
  const now = taiwanNowString();
  const config = data.config || data.richMenuConfig || {};
  const rawId = String(data.id || "").trim();
  const rawAliasId = String(data.aliasId || data.alias_id || config.aliasId || config.richMenuAliasId || "").trim();
  const aliasGuard = guardReservedRichMenuProjectAlias(rawId, rawAliasId);
  if (!aliasGuard.ok) return { success: false, message: aliasGuard.message };
  const id = aliasGuard.id || crypto.randomUUID();
  const name = String(data.name || config.name || "未命名圖文選單").trim().slice(0, 300);
  const chatBarText = String(data.chatBarText || config.chatBarText || "選單").trim().slice(0, 14);
  let imageUrl = String(data.imageUrl || data.image_url || "").trim();
  let imageKey = String(data.imageKey || data.image_key || "").trim();
  let imageMimeType = String(data.imageMimeType || data.image_mime_type || "").trim();

  if (data.imageBase64) {
    if (!env.R2_BUCKET) return { success: false, message: "R2_BUCKET 尚未設定，無法儲存 Rich Menu 底圖。" };
    const image = dataUrlToUint8Array(data.imageBase64);
    const origin = new URL(request.url).origin;
    const stored = await storeBinaryFile(
      env.R2_BUCKET,
      origin,
      "rich_menu_" + id + "_" + Date.now(),
      (data.imageName || name || "rich-menu") + "." + extensionFromMime(image.contentType),
      image.bytes,
      image.contentType
    );
    imageUrl = stored.url;
    imageKey = stored.key;
    imageMimeType = image.contentType;
  }

  const normalizedConfig = {
    ...config,
    name,
    chatBarText,
    aliasId: aliasGuard.aliasId || rawAliasId,
    selected: config.selected !== false,
    areas: Array.isArray(config.areas) ? config.areas : [],
  };

  await db.prepare(`
    INSERT INTO rich_menu_projects (
      id, name, chat_bar_text, config_json, image_url, image_key, image_mime_type,
      owner_uid, created_at, updated_at, deployed_rich_menu_id, deployed_at
    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    ON CONFLICT(id) DO UPDATE SET
      name = excluded.name,
      chat_bar_text = excluded.chat_bar_text,
      config_json = excluded.config_json,
      image_url = CASE WHEN excluded.image_url <> '' THEN excluded.image_url ELSE rich_menu_projects.image_url END,
      image_key = CASE WHEN excluded.image_key <> '' THEN excluded.image_key ELSE rich_menu_projects.image_key END,
      image_mime_type = CASE WHEN excluded.image_mime_type <> '' THEN excluded.image_mime_type ELSE rich_menu_projects.image_mime_type END,
      owner_uid = excluded.owner_uid,
      updated_at = excluded.updated_at,
      deployed_rich_menu_id = CASE WHEN excluded.deployed_rich_menu_id <> '' THEN excluded.deployed_rich_menu_id ELSE rich_menu_projects.deployed_rich_menu_id END,
      deployed_at = CASE WHEN excluded.deployed_at <> '' THEN excluded.deployed_at ELSE rich_menu_projects.deployed_at END
  `).bind(
    id,
    name,
    chatBarText,
    JSON.stringify(normalizedConfig),
    imageUrl,
    imageKey,
    imageMimeType,
    String(data.ownerUid || data.owner_uid || "").trim(),
    now,
    now,
    String(data.deployedRichMenuId || data.deployed_rich_menu_id || "").trim(),
    String(data.deployedAt || data.deployed_at || "").trim()
  ).run();

  return {
    success: true,
    message: "Rich Menu 專案已儲存。",
    data: { id, name, chatBarText, imageUrl, imageKey, imageMimeType, config: normalizedConfig, updatedAt: now },
  };
}

async function deleteRichMenuProject(db, data) {
  if (!db) return { success: false, message: "D1 binding DB is not configured." };
  const id = String(data.id || "").trim();
  if (!id) return { success: false, message: "缺少 Rich Menu 專案 id。" };
  const defaultHomeProjectId = await getDefaultHomeRichMenuProjectId(db);
  await db.prepare(`DELETE FROM rich_menu_projects WHERE id = ?`).bind(id).run();
  if (id === defaultHomeProjectId) await setSystemSetting(db, RICH_MENU_DEFAULT_HOME_SETTING_KEY, "");
  return { success: true, message: "Rich Menu 專案已刪除。" };
}

async function setDefaultHomeRichMenuProject(db, env, data) {
  if (!db) return { success: false, message: "D1 binding DB is not configured." };
  const id = String(data.id || data.projectId || "").trim();
  if (!id) return { success: false, message: "缺少 Rich Menu 專案 id。" };
  const row = await db.prepare(`
    SELECT id, name, config_json, deployed_rich_menu_id
    FROM rich_menu_projects
    WHERE id = ?
  `).bind(id).first();
  if (!row) return { success: false, message: "找不到 Rich Menu 專案。" };
  const config = parseJsonObject(row.config_json);
  const aliasId = getRichMenuProjectAlias(config);
  if (!isVisitorDefaultRichMenuAlias(aliasId)) {
    return { success: false, message: richMenuDefaultHomeGuardMessage(aliasId) };
  }
  const richMenuId = String(row.deployed_rich_menu_id || "").trim();
  let lineDefaultResult = { ok: true, status: 0, text: "not deployed", skipped: true };
  let guestAliasId = "";
  if (richMenuId) {
    if (!env.LINE_CHANNEL_ACCESS_TOKEN) return { success: false, message: "LINE_CHANNEL_ACCESS_TOKEN is not configured." };
    lineDefaultResult = await lineApi("https://api.line.me/v2/bot/user/all/richmenu/" + encodeURIComponent(richMenuId), env, {
      method: "POST",
      body: "",
      contentType: "application/json",
    });
    if (!lineDefaultResult.ok) {
      return { success: false, message: "Set default Rich Menu failed: " + lineDefaultResult.text, data: { richMenuId, lineDefaultResult } };
    }
    guestAliasId = await upsertRichMenuAlias(env, VISITOR_DEFAULT_RICH_MENU_ALIAS_ID, richMenuId);
    await db.prepare(`
      UPDATE rich_menu_bindings
      SET rich_menu_id = ?, updated_at = ?
      WHERE rich_menu_alias_id = ?
    `).bind(richMenuId, taiwanNowString(), VISITOR_DEFAULT_RICH_MENU_ALIAS_ID).run();
  }
  await setSystemSetting(db, RICH_MENU_DEFAULT_HOME_SETTING_KEY, id);
  return {
    success: true,
    message: richMenuId ? "已設定訪客預設首頁，並同步 LINE 全域預設。" : "已設定訪客預設首頁；此專案尚未部署，部署後才會同步到 LINE。",
    data: { id, richMenuId, guestAliasId, lineDefaultResult },
  };
}

async function fetchLineRichMenuDefinition(env, richMenuId) {
  const normalized = String(richMenuId || "").trim();
  if (!normalized.startsWith("richmenu-")) return { ok: false, status: 0, text: "Missing richMenuId.", json: null };
  if (!env || !env.LINE_CHANNEL_ACCESS_TOKEN) return { ok: false, status: 0, text: "LINE_CHANNEL_ACCESS_TOKEN is not configured.", json: null };
  return lineApi("https://api.line.me/v2/bot/richmenu/" + encodeURIComponent(normalized), env, {
    method: "GET",
    body: undefined,
    contentType: "application/json",
  });
}

function collectLineRichMenuSwitchAliases(json) {
  const areas = Array.isArray(json && json.areas) ? json.areas : [];
  const aliases = [];
  areas.forEach((area, index) => {
    const action = area && area.action ? area.action : {};
    let aliasId = "";
    if (action.type === "richmenuswitch") aliasId = normalizeRichMenuAliasId(action.richMenuAliasId || "");
    if (!aliasId && String(action.data || "").startsWith("switch:")) aliasId = normalizeRichMenuAliasId(String(action.data).slice("switch:".length));
    if (aliasId) aliases.push({ aliasId, index: index + 1, data: String(action.data || "") });
  });
  return aliases;
}
async function runRichMenuSwitchDiagnose(db, env, data = {}) {
  if (!db) return { success: false, message: "D1 binding DB is not configured." };
  await ensureRichMenuSwitchChecksTable(db);
  const groupId = "diag:" + Date.now() + ":" + crypto.randomUUID();
  const rows = await db.prepare(`
    SELECT id, name, config_json, deployed_rich_menu_id, updated_at, deployed_at
    FROM rich_menu_projects
    ORDER BY
      CASE WHEN COALESCE(deployed_rich_menu_id, '') <> '' THEN 0 ELSE 1 END,
      updated_at DESC
    LIMIT 200
  `).all();
  const projects = (rows.results || []).map((row) => {
    const config = parseJsonObject(row.config_json);
    const aliasId = normalizeRichMenuAliasId(config.aliasId || config.richMenuAliasId || "");
    const areas = Array.isArray(config.areas) ? config.areas : [];
    return { row, config, aliasId, areas };
  });
  const aliasMap = new Map();
  for (const project of projects) {
    if (project.aliasId) aliasMap.set(project.aliasId, project);
  }
  const targets = [];
  const requestedAlias = normalizeRichMenuAliasId(data.aliasId || data.alias_id || "");
  for (const project of projects) {
    if (requestedAlias && project.aliasId !== requestedAlias) continue;
    if (project.aliasId) {
      targets.push({ kind: "page_alias", project, sourceAliasId: project.aliasId, targetAliasId: project.aliasId, expected: String(project.row.deployed_rich_menu_id || "") });
    }
    for (const area of project.areas) {
      const action = area && area.action ? area.action : {};
      if (action.type !== "richmenuswitch") continue;
      const targetAliasId = normalizeRichMenuAliasId(action.richMenuAliasId || "");
      if (!targetAliasId) continue;
      const targetProject = aliasMap.get(targetAliasId);
      targets.push({
        kind: "switch_target",
        project,
        sourceAliasId: project.aliasId,
        targetAliasId,
        expected: targetProject ? String(targetProject.row.deployed_rich_menu_id || "") : "",
      });
    }
  }
  const seen = new Set();
  const uniqueTargets = targets.filter((target) => {
    const key = [target.kind, target.sourceAliasId, target.targetAliasId].join("|");
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
  const results = [];
  for (const target of uniqueTargets) {
    const started = Date.now();
    const resolved = target.targetAliasId ? await resolveLineRichMenuAliasFresh(env, target.targetAliasId) : { richMenuId: "", status: 0, source: "missing_alias" };
    const latencyMs = Date.now() - started;
    const expected = target.expected || "";
    const lineRichMenuId = String(resolved.richMenuId || "");
    const ok = Boolean(lineRichMenuId && (!expected || lineRichMenuId === expected));
    const note = !target.targetAliasId
      ? "缺少 alias"
      : (!lineRichMenuId ? "LINE alias 查無 richMenuId" : (expected && lineRichMenuId !== expected ? "D1 deployed richMenuId 與 LINE alias 指向不一致" : "alias 正常"));
    const row = {
      id: crypto.randomUUID(),
      checkGroupId: groupId,
      kind: target.kind,
      projectId: target.project.row.id || "",
      projectName: target.project.row.name || "",
      sourceAliasId: target.sourceAliasId || "",
      targetAliasId: target.targetAliasId || "",
      d1RichMenuId: expected,
      lineRichMenuId,
      lineStatus: Number(resolved.status || 0),
      latencyMs,
      ok: ok ? 1 : 0,
      note,
      checkedAt: taiwanNowString(),
      source: resolved.source || "",
    };
    await db.prepare(`
      INSERT INTO rich_menu_switch_checks (
        id, check_group_id, kind, project_id, project_name, source_alias_id, target_alias_id,
        d1_rich_menu_id, line_rich_menu_id, line_status, latency_ms, ok, note, checked_at, raw_payload
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `).bind(
      row.id, row.checkGroupId, row.kind, row.projectId, row.projectName, row.sourceAliasId, row.targetAliasId,
      row.d1RichMenuId, row.lineRichMenuId, row.lineStatus, row.latencyMs, row.ok, row.note, row.checkedAt,
      JSON.stringify(resolved)
    ).run();
    results.push(row);
  }
  const sourceMenuCache = new Map();
  const sourceActionTargets = uniqueTargets.filter((target) => target.kind === "switch_target" && target.targetAliasId);
  for (const target of sourceActionTargets) {
    const started = Date.now();
    const sourceRichMenuId = String(target.project.row.deployed_rich_menu_id || "").trim();
    let fetchResult = sourceMenuCache.get(sourceRichMenuId);
    if (!fetchResult) {
      fetchResult = sourceRichMenuId ? await fetchLineRichMenuDefinition(env, sourceRichMenuId) : { ok: false, status: 0, text: "來源選單尚未部署。", json: null };
      if (sourceRichMenuId) sourceMenuCache.set(sourceRichMenuId, fetchResult);
    }
    const aliases = fetchResult.ok ? collectLineRichMenuSwitchAliases(fetchResult.json) : [];
    const hit = aliases.find((item) => item.aliasId === target.targetAliasId);
    const ok = Boolean(fetchResult.ok && hit);
    const note = !sourceRichMenuId
      ? "來源選單尚未部署，無法切換。"
      : (!fetchResult.ok
        ? "無法讀取來源 LINE Rich Menu：" + String(fetchResult.status || fetchResult.text || "").slice(0, 180)
        : (ok ? "來源 LINE 熱區包含 richmenuswitch -> " + target.targetAliasId : "來源 LINE 熱區缺少 richmenuswitch -> " + target.targetAliasId + "，請重新部署來源選單。"));
    const row = {
      id: crypto.randomUUID(),
      checkGroupId: groupId,
      kind: "source_action",
      projectId: target.project.row.id || "",
      projectName: target.project.row.name || "",
      sourceAliasId: target.sourceAliasId || "",
      targetAliasId: target.targetAliasId || "",
      d1RichMenuId: sourceRichMenuId,
      lineRichMenuId: fetchResult.ok ? sourceRichMenuId : "",
      lineStatus: Number(fetchResult.status || 0),
      latencyMs: Date.now() - started,
      ok: ok ? 1 : 0,
      note,
      checkedAt: taiwanNowString(),
      source: "line_source_menu",
    };
    await db.prepare(`
      INSERT INTO rich_menu_switch_checks (
        id, check_group_id, kind, project_id, project_name, source_alias_id, target_alias_id,
        d1_rich_menu_id, line_rich_menu_id, line_status, latency_ms, ok, note, checked_at, raw_payload
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `).bind(
      row.id, row.checkGroupId, row.kind, row.projectId, row.projectName, row.sourceAliasId, row.targetAliasId,
      row.d1RichMenuId, row.lineRichMenuId, row.lineStatus, row.latencyMs, row.ok, row.note, row.checkedAt,
      JSON.stringify({ expectedAlias: target.targetAliasId, actualAliases: aliases, fetchStatus: fetchResult.status, fetchText: fetchResult.text || "" })
    ).run();
    results.push(row);
  }
  return {
    success: true,
    message: "Rich Menu 切換診斷完成。",
    data: {
      groupId,
      total: results.length,
      ok: results.filter((row) => row.ok).length,
      failed: results.filter((row) => !row.ok).length,
      rows: results,
    },
  };
}

async function listRichMenuSwitchChecks(db, data = {}) {
  if (!db) return { success: false, message: "D1 binding DB is not configured." };
  await ensureRichMenuSwitchChecksTable(db);
  const limit = Math.min(200, Math.max(1, Number(data.limit || 80)));
  const rows = await db.prepare(`
    SELECT *
    FROM rich_menu_switch_checks
    ORDER BY checked_at DESC, rowid DESC
    LIMIT ?
  `).bind(limit).all();
  return { success: true, data: rows.results || [] };
}
function extensionFromMime(contentType) {
  const type = String(contentType || "").toLowerCase();
  if (type.includes("png")) return "png";
  if (type.includes("webp")) return "webp";
  if (type.includes("gif")) return "gif";
  return "jpg";
}

const DEFAULT_BUSINESS_UNITS = [
  "總管理處", "製造管理處", "營業管理處", "服務管理處", "品牌/產品管理處",
  "海外事業處", "廚電事業處", "廚櫃事業處", "櫻花家居", "雅適",
  "櫻中", "櫻順", "越南子公司台幹", "櫻花總經銷", "廚藝生活館",
  "太陽能總代理", "其他"
];

async function deployAndSaveRichMenu(data, db, env, request) {
  const config = data.richMenuConfig || {};
  const requestedDefault = data.setDefault === true || data.setAsDefault === true || config.isDefaultHome === true;
  const requestedAliasId = normalizeRichMenuAliasId(data.aliasId || config.aliasId || config.richMenuAliasId || config.name || "");
  if (requestedDefault && !isVisitorDefaultRichMenuAlias(requestedAliasId)) {
    return { success: false, message: richMenuDefaultHomeGuardMessage(requestedAliasId) };
  }
  const result = await deployRichMenuToLine(data, env);
  if (!result || !result.success) return result;
  const richMenuId = String(result.data && result.data.richMenuId || "").trim();
  const richMenuAliasId = normalizeRichMenuAliasId(result.data && result.data.richMenuAliasId || data.aliasId || (data.richMenuConfig && data.richMenuConfig.aliasId) || "");
  if (db) {
    const projectId = String(data.id || config.id || richMenuAliasId || normalizeRichMenuAliasId(config.name) || crypto.randomUUID()).trim();
    const saveResult = await saveRichMenuProject(db, env, request, {
      id: projectId,
      name: config.name || data.name || projectId,
      chatBarText: config.chatBarText || data.chatBarText || "選單",
      config: { ...config, aliasId: richMenuAliasId, deployedRichMenuId: richMenuId },
      imageBase64: data.imageBase64 || "",
      imageName: config.name || data.name || projectId,
      deployedRichMenuId: richMenuId,
      deployedAt: taiwanNowString(),
    });
    result.data.project = saveResult && saveResult.data ? saveResult.data : null;
    if (requestedDefault && isVisitorDefaultRichMenuAlias(richMenuAliasId)) {
      await setSystemSetting(db, RICH_MENU_DEFAULT_HOME_SETTING_KEY, projectId);
      if (richMenuId && env.LINE_CHANNEL_ACCESS_TOKEN) {
        await upsertRichMenuAlias(env, VISITOR_DEFAULT_RICH_MENU_ALIAS_ID, richMenuId);
        await db.prepare(`
          UPDATE rich_menu_bindings
          SET rich_menu_id = ?, updated_at = ?
          WHERE rich_menu_alias_id = ?
        `).bind(richMenuId, taiwanNowString(), VISITOR_DEFAULT_RICH_MENU_ALIAS_ID).run();
      }
    }
    if (richMenuAliasId && richMenuId) {
      await db.prepare(`
        UPDATE rich_menu_bindings
        SET rich_menu_id = ?, updated_at = ?
        WHERE rich_menu_alias_id = ?
      `).bind(richMenuId, taiwanNowString(), richMenuAliasId).run();
    }
  }
  return result;
}
async function deployRichMenuToLine(data, env) {
  if (!env.LINE_CHANNEL_ACCESS_TOKEN) {
    return { success: false, message: "LINE_CHANNEL_ACCESS_TOKEN is not configured." };
  }

  const config = data.richMenuConfig || {};
  const requestedDefault = data.setDefault === true || data.setAsDefault === true || config.isDefaultHome === true;
  const requestedAliasId = normalizeRichMenuAliasId(data.aliasId || config.aliasId || config.richMenuAliasId || config.name || "");
  if (requestedDefault && !isVisitorDefaultRichMenuAlias(requestedAliasId)) {
    return { success: false, message: richMenuDefaultHomeGuardMessage(requestedAliasId) };
  }
  const imageBase64 = String(data.imageBase64 || "");
  const imageSourceUrl = String(data.imageUrl || data.image_url || config.imageUrl || config.image_url || "").trim();
  if (!config.name || !config.chatBarText || !config.size || !Array.isArray(config.areas) || config.areas.length === 0) {
    return { success: false, message: "Rich Menu config is incomplete." };
  }

  const normalizedSwitch = normalizeRichMenuSwitchActions(config);
  if (!normalizedSwitch.success) {
    return { success: false, message: normalizedSwitch.message };
  }

  const richMenuPayload = {
    size: {
      width: Number(config.size.width || 2500),
      height: Number(config.size.height),
    },
    selected: config.selected !== false,
    name: String(config.name).slice(0, 300),
    chatBarText: String(config.chatBarText).slice(0, 14),
    areas: normalizedSwitch.config.areas.map((area) => ({
      bounds: {
        x: Math.max(0, Number(area.bounds && area.bounds.x || 0)),
        y: Math.max(0, Number(area.bounds && area.bounds.y || 0)),
        width: Math.max(1, Number(area.bounds && area.bounds.width || 1)),
        height: Math.max(1, Number(area.bounds && area.bounds.height || 1)),
      },
      action: sanitizeRichMenuAction(area.action || {}),
    })),
  };

  const createResult = await lineApi("https://api.line.me/v2/bot/richmenu", env, {
    method: "POST",
    body: JSON.stringify(richMenuPayload),
    contentType: "application/json",
  });
  if (!createResult.ok) {
    return { success: false, message: "Create Rich Menu failed: " + createResult.text, data: createResult };
  }

  const richMenuId = createResult.json && createResult.json.richMenuId;
  if (!richMenuId) {
    return { success: false, message: "LINE did not return richMenuId.", data: createResult };
  }

  const image = await loadRichMenuImageBytes(imageBase64, imageSourceUrl);
  if (!image.success) return image;
  const uploadResult = await lineApi("https://api-data.line.me/v2/bot/richmenu/" + encodeURIComponent(richMenuId) + "/content", env, {
    method: "POST",
    body: image.data.bytes,
    contentType: image.data.contentType,
  });
  if (!uploadResult.ok) {
    return { success: false, message: "Upload Rich Menu image failed: " + uploadResult.text, data: uploadResult };
  }

  let defaultResult = { ok: true, status: 0, text: "skipped", skipped: true };
  const shouldSetDefault = requestedDefault && config.selected !== false;
  if (shouldSetDefault) {
    defaultResult = await lineApi("https://api.line.me/v2/bot/user/all/richmenu/" + encodeURIComponent(richMenuId), env, {
      method: "POST",
      body: "",
      contentType: "application/json",
    });
    if (!defaultResult.ok) {
      return { success: false, message: "Set default Rich Menu failed: " + defaultResult.text, data: { richMenuId, defaultResult } };
    }
  }

  let richMenuAliasId = "";
  try {
    richMenuAliasId = await upsertRichMenuAlias(
      env,
      data.aliasId || config.aliasId || config.name,
      richMenuId
    );
  } catch (err) {
    return {
      success: false,
      message: err && err.message ? err.message : "Create/update Rich Menu alias failed.",
      data: { richMenuId },
    };
  }

  return {
    success: true,
    message: shouldSetDefault ? "Rich Menu deployed and set as visitor default." : "Rich Menu deployed without changing global default.",
    data: { richMenuId, richMenuAliasId, defaultResult },
  };
}

function normalizeRichMenuAliasId(value) {
  return String(value || "")
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9_-]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 32);
}

function normalizeRichMenuSwitchData(_value, aliasId) {
  const targetAliasId = normalizeRichMenuAliasId(aliasId);
  return targetAliasId ? "switch:" + targetAliasId : "";
}

function normalizeRichMenuSwitchActions(config) {
  const cloned = {
    ...config,
    areas: Array.isArray(config.areas) ? config.areas.map((area) => ({ ...area, action: { ...(area.action || {}) } })) : [],
  };
  for (const area of cloned.areas) {
    const action = area.action || {};
    if (action.type !== "richmenuswitch") continue;
    const aliasId = normalizeRichMenuAliasId(action.richMenuAliasId);
    if (!aliasId) {
      return {
        success: false,
        message: "切換選單區域缺少可用的 Alias ID，請填 menu1/menu2 這類英文別名。",
      };
    }
    area.action = {
      type: "richmenuswitch",
      richMenuAliasId: aliasId,
      data: normalizeRichMenuSwitchData(action.data, aliasId),
    };
  }
  return { success: true, config: cloned };
}

async function upsertRichMenuAlias(env, richMenuAliasId, richMenuId) {
  const aliasId = normalizeRichMenuAliasId(richMenuAliasId);
  if (!aliasId || !richMenuId) return "";
  richMenuAliasCache.set(aliasId, { richMenuId, expiresAt: Date.now() + RICH_MENU_ALIAS_CACHE_TTL_MS });
  const payload = JSON.stringify({ richMenuAliasId: aliasId, richMenuId });
  const createResult = await lineApi("https://api.line.me/v2/bot/richmenu/alias", env, {
    method: "POST",
    body: payload,
    contentType: "application/json",
  });
  if (createResult.ok) return aliasId;

  const updateResult = await lineApi("https://api.line.me/v2/bot/richmenu/alias/" + encodeURIComponent(aliasId), env, {
    method: "POST",
    body: JSON.stringify({ richMenuId }),
    contentType: "application/json",
  });
  if (!updateResult.ok) {
    throw new Error("Create/update Rich Menu alias failed: create=" + createResult.text + "; update=" + updateResult.text);
  }
  return aliasId;
}

function sanitizeRichMenuAction(action) {
  const type = String(action.type || "message");
  if (type === "uri") return { type: "uri", uri: String(action.uri || "") };
  if (type === "postback") {
    const result = { type: "postback", data: String(action.data || "") };
    if (action.displayText) result.displayText = String(action.displayText);
    return result;
  }
  if (type === "richmenuswitch") {
    const richMenuAliasId = normalizeRichMenuAliasId(action.richMenuAliasId);
    return {
      type: "richmenuswitch",
      richMenuAliasId,
      data: normalizeRichMenuSwitchData(action.data, richMenuAliasId),
    };
  }
  return { type: "message", text: String(action.text || "") };
}

async function lineApi(url, env, options) {
  const response = await fetch(url, {
    method: options.method || "GET",
    headers: {
      Authorization: "Bearer " + env.LINE_CHANNEL_ACCESS_TOKEN,
      "Content-Type": options.contentType || "application/json",
    },
    body: options.body,
  });
  const text = await response.text();
  let json = null;
  try {
    json = text ? JSON.parse(text) : null;
  } catch (err) {
    json = null;
  }
  return { ok: response.ok, status: response.status, text, json };
}

async function loadRichMenuImageBytes(imageBase64, imageSourceUrl) {
  if (String(imageBase64 || "").startsWith("data:image/")) {
    try {
      return { success: true, data: dataUrlToUint8Array(imageBase64) };
    } catch (err) {
      return { success: false, message: err && err.message ? err.message : "Invalid Rich Menu image base64." };
    }
  }
  if (!imageSourceUrl) return { success: false, message: "Missing Rich Menu image base64 or imageUrl." };
  try {
    const response = await fetch(imageSourceUrl);
    if (!response.ok) return { success: false, message: "Fetch Rich Menu image failed: HTTP " + response.status };
    const contentType = response.headers.get("content-type") || "image/jpeg";
    const bytes = new Uint8Array(await response.arrayBuffer());
    return { success: true, data: { contentType, bytes } };
  } catch (err) {
    return { success: false, message: "Fetch Rich Menu image failed: " + (err && err.message ? err.message : String(err)) };
  }
}
function dataUrlToUint8Array(dataUrl) {
  const match = String(dataUrl).match(/^data:([^;]+);base64,(.+)$/);
  if (!match) throw new Error("Invalid image base64 data URL.");
  const binary = atob(match[2]);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return { contentType: match[1] || "image/jpeg", bytes };
}

async function loginAdmin(data, db, request) {
  const username = String(data.username || "").trim();
  const password = String(data.password || "");
  if (!username || !password) return { success: false, message: "Please enter username and password." };

  const user = await db.prepare(`
    SELECT id, username, display_name, role, business_units
    FROM admin_users
    WHERE username = ? AND password = ? AND active = 1
  `).bind(username, password).first();

  if (!user) return { success: false, message: "Invalid username or password." };

  const session = await createAdminSession(db, user, request, "login");
  return {
    success: true,
    message: "Login successful.",
    data: session
  };
}

async function createAdminSession(db, user, request, action) {
  const token = crypto.randomUUID();
  const expiresAt = new Date(Date.now() + 8 * 60 * 60 * 1000).toISOString();
  await db.prepare("INSERT INTO admin_sessions (token, user_id, expires_at) VALUES (?, ?, ?)")
    .bind(token, user.id, expiresAt)
    .run();
  await logAdminActivity(db, user, action || "login", {
    detail: "後台登入",
    request
  });

  return {
    token,
    username: user.username,
    displayName: user.display_name || user.username,
    role: user.role,
    businessUnits: user.business_units
  };
}

async function requireAdmin(data, db) {
  const token = String(data.sessionToken || "");
  if (!token) return { ok: false, response: { success: false, message: "Please login first." } };

  const user = await db.prepare(`
    SELECT u.id, u.username, u.display_name, u.role, u.business_units
    FROM admin_sessions s
    JOIN admin_users u ON u.id = s.user_id
    WHERE s.token = ? AND s.expires_at > ? AND u.active = 1
  `).bind(token, new Date().toISOString()).first();

  if (!user) return { ok: false, response: { success: false, message: "Login expired. Please login again." } };
  user.permissions = await loadUserPermissions(db, user.id);
  return { ok: true, user };
}

async function loadUserPermissions(db, userId) {
  try {
    const result = await db.prepare(`
      SELECT business_unit, review_stage
      FROM admin_user_permissions
      WHERE user_id = ? AND active = 1
    `).bind(userId).all();
    return result.results || [];
  } catch (err) {
    return [];
  }
}

function hasReviewPermission(user, businessUnit, stage) {
  if (!user || user.role === "admin") return true;
  const permissions = user.permissions || [];
  if (permissions.length) {
    return permissions.some(item => {
      const unitOk = item.business_unit === "*" || String(item.business_unit || "") === String(businessUnit || "");
      const stageOk = item.review_stage === stage || item.review_stage === "both";
      return unitOk && stageOk;
    });
  }
  const scope = String(user.business_units || "*");
  const unitOk = scope === "*" || scope.split(",").map(item => item.trim()).includes(String(businessUnit || ""));
  if (!unitOk) return false;
  if (stage === "prelim") return user.role === "prelim" || user.role === "reviewer";
  if (stage === "final") return user.role === "final" || user.role === "reviewer";
  return true;
}

function canAccessBusinessUnit(user, businessUnit) {
  if (!user || user.role === "admin") return true;
  const permissions = user.permissions || [];
  if (permissions.length) {
    return permissions.some(item => item.business_unit === "*" || String(item.business_unit || "") === String(businessUnit || ""));
  }
  const scope = String(user.business_units || "*");
  return scope === "*" || scope.split(",").map(item => item.trim()).includes(String(businessUnit || ""));
}

function reviewStageForStatus(newStatus) {
  const status = String(newStatus || "");
  if (status.includes("初")) return "prelim";
  if (status.includes("複") || status.includes("獲") || status.includes("得獎") || status.includes("條件") || status.includes("退件")) return "final";
  return "any";
}

function canUpdateStatus(user, newStatus, businessUnit) {
  if (!user) return false;
  if (user.role === "admin") return true;
  const stage = reviewStageForStatus(newStatus);
  if (stage === "any") {
    return hasReviewPermission(user, businessUnit, "prelim") || hasReviewPermission(user, businessUnit, "final");
  }
  return hasReviewPermission(user, businessUnit, stage);
}

async function submitApplication(data, db) {
  const now = new Date().toISOString();
  const reviewers = await findReviewers(db, data.businessUnit);

  if (data.editAppId) {
    const existing = await db.prepare("SELECT app_id FROM applications WHERE app_id = ? AND deleted_at IS NULL")
      .bind(data.editAppId)
      .first();
    if (!existing) return { success: false, message: "Application not found." };

    await db.prepare(`
      UPDATE applications SET
        updated_at = ?, application_year = ?, academic_year = ?, group_name = ?, student_name = ?, gender = ?,
        school = ?, grade = ?, department = ?, age = ?, intellect_top = ?, intellect_bottom = ?,
        moral_top = ?, moral_bottom = ?, talent_organizer = ?, talent_category = ?, talent_result = ?,
        message_to_sakura = ?, employee_name = ?, relationship = ?, applicant_name = ?, business_unit = ?,
        employee_dept = ?, employee_id = ?, phone = ?, email = ?, address = ?, applicant_confirm = ?,
        confirm_date = ?, agree_terms = ?, photo_url = COALESCE(NULLIF(?, ''), photo_url),
        transcript_url = COALESCE(NULLIF(?, ''), transcript_url),
        transcript_urls_json = COALESCE(NULLIF(?, ''), transcript_urls_json),
        prelim_status = 'submitted', status = 'submitted', supplement_note = '',
        prelim_reviewer = ?, final_reviewer = ?
      WHERE app_id = ? AND deleted_at IS NULL
    `).bind(
      now, data.applicationYear || "2026", data.academicYear || "113", data.group || "", data.studentName || "", data.gender || "",
      data.school || "", data.grade || "", data.department || "", data.age || "", data.intellectTop || "", data.intellectBottom || "",
      data.moralTop || "", data.moralBottom || "", data.talentOrganizer || "", data.talentCategory || "", data.talentResult || "",
      data.messageToSakura || "", data.employeeName || "", data.relationship || "", data.applicantName || "", data.businessUnit || "",
      data.employeeDept || "", String(data.employeeId || "").toUpperCase(), data.phone || "", data.email || "", data.address || "",
      data.applicantConfirm || "", data.confirmDate || "", data.agreeTerms ? 1 : 0, data.photoUrl || "", data.transcriptUrl || "",
      data.transcriptUrls ? JSON.stringify(data.transcriptUrls) : "", reviewers.prelimReviewer, reviewers.finalReviewer, data.editAppId
    ).run();

    await logAction(db, data.editAppId, "submit_update", "", "submitted", "");
    return { success: true, message: "Application updated.", data: { appId: data.editAppId } };
  }

  const appId = await nextApplicationId(db);
  await db.prepare(`
    INSERT INTO applications (
      app_id, created_at, updated_at, application_year, academic_year, group_name, student_name, gender,
      school, grade, department, age, intellect_top, intellect_bottom, moral_top, moral_bottom,
      talent_organizer, talent_category, talent_result, message_to_sakura, employee_name, relationship,
      applicant_name, business_unit, employee_dept, employee_id, phone, email, address, applicant_confirm,
      confirm_date, agree_terms, photo_url, transcript_url, transcript_urls_json, prelim_status,
      final_status, status, supplement_note, prelim_reviewer, final_reviewer
    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
  `).bind(
    appId, now, now, data.applicationYear || "2026", data.academicYear || "113", data.group || "", data.studentName || "", data.gender || "",
    data.school || "", data.grade || "", data.department || "", data.age || "", data.intellectTop || "", data.intellectBottom || "",
    data.moralTop || "", data.moralBottom || "", data.talentOrganizer || "", data.talentCategory || "", data.talentResult || "",
    data.messageToSakura || "", data.employeeName || "", data.relationship || "", data.applicantName || "", data.businessUnit || "",
    data.employeeDept || "", String(data.employeeId || "").toUpperCase(), data.phone || "", data.email || "", data.address || "",
    data.applicantConfirm || "", data.confirmDate || "", data.agreeTerms ? 1 : 0, data.photoUrl || "", data.transcriptUrl || "",
    data.transcriptUrls ? JSON.stringify(data.transcriptUrls) : "", "pending", "pending", "pending", "", reviewers.prelimReviewer, reviewers.finalReviewer
  ).run();

  await logAction(db, appId, "submit_create", "", "pending", "");
  return { success: true, message: "Application submitted.", data: { appId } };
}

