async function getAllApplications(data, db, env) {
  const auth = await requireAdmin(data, db);
  if (!auth.ok) return auth.response;

  let result;
  const permissionUnits = Array.from(new Set((auth.user.permissions || []).map(item => item.business_unit).filter(Boolean)));
  if (auth.user.role === "admin" || permissionUnits.includes("*") || (!permissionUnits.length && String(auth.user.business_units || "*") === "*")) {
    result = await db.prepare(`
      SELECT * FROM applications
      WHERE deleted_at IS NULL
      ORDER BY created_at DESC, id DESC
    `).all();
  } else {
    const units = permissionUnits.length ? permissionUnits : String(auth.user.business_units || "").split(",").map(item => item.trim()).filter(Boolean);
    if (!units.length) return { success: true, data: [] };
    const placeholders = units.map(() => "?").join(",");
    result = await db.prepare(`
      SELECT * FROM applications
      WHERE deleted_at IS NULL AND business_unit IN (${placeholders})
      ORDER BY created_at DESC, id DESC
    `).bind(...units).all();
  }

  await logAdminActivity(db, auth.user, "view_applications", {
    detail: "查看後台申請列表"
  });
  return { success: true, data: (result.results || []).map(toClientObject) };
}

async function updateApplicationStatus(data, db, env) {
  const auth = await requireAdmin(data, db);
  if (!auth.ok) return auth.response;
  const id = Number(data.rowIndex);
  const current = await db.prepare("SELECT * FROM applications WHERE id = ? AND deleted_at IS NULL").bind(id).first();
  if (!current) return { success: false, message: "Application not found." };
  if (!canAccessBusinessUnit(auth.user, current.business_unit)) return { success: false, message: "Permission denied." };
  if (!canUpdateStatus(auth.user, data.newStatus, current.business_unit)) return { success: false, message: "Permission denied." };
  let prelimStatus = current.prelim_status;
  let finalStatus = current.final_status;
  let status = data.newStatus || current.status;
  const normalizedStatus = normalizeScholarshipStatus(data.newStatus);
  if (normalizedStatus === "初審通過") { prelimStatus = "初審通過"; finalStatus = current.final_status || "待複審"; status = "待複審"; }
  else if (normalizedStatus === "複審通過") { finalStatus = "複審通過"; status = "複審通過"; }
  else if (normalizedStatus === "需要補件") { prelimStatus = "需要補件"; status = "需要補件"; }
  else if (normalizedStatus === "條件不符") { finalStatus = "條件不符"; status = "條件不符"; }
  else if (normalizedStatus === "獲得獎學金") { finalStatus = "獲得獎學金"; status = "獲得獎學金"; }
  await db.prepare("UPDATE applications SET updated_at = ?, prelim_status = ?, final_status = ?, status = ?, supplement_note = ? WHERE id = ? AND deleted_at IS NULL")
    .bind(new Date().toISOString(), prelimStatus, finalStatus, status, data.note || "", id).run();
  await logAction(db, current.app_id, "update_status", current.status, status, data.note || "");
  const mailResult = await sendScholarshipStatusEmail(env, { ...current, status }, status, data.note || "");
  await logAdminActivity(db, auth.user, "update_status", {
    targetAppId: current.app_id,
    targetRowId: id,
    detail: "狀態：" + current.status + " -> " + status + (data.note ? "；說明：" + data.note : "") + (mailResult.sent ? "；Email 已寄出" : "；Email 未寄出：" + mailResult.reason)
  });
  return { success: true, message: "Status updated." + (mailResult.sent ? " Email sent." : " Email skipped: " + mailResult.reason) };
}

function normalizeScholarshipStatus(value) {
  const status = String(value || "");
  if (status.includes("獲")) return "獲得獎學金";
  if (status.includes("條件") || status.includes("退件") || status.includes("不符")) return "條件不符";
  if (status.includes("補")) return "需要補件";
  if (status.includes("複")) return "複審通過";
  if (status.includes("初")) return "初審通過";
  return status || "審核中";
}

async function sendScholarshipStatusEmail(env, application, status, note) {
  const to = String(application.email || "").trim();
  if (!to) return { sent: false, reason: "no applicant email" };
  const subject = scholarshipEmailSubject(status, application);
  const text = scholarshipEmailText(status, application, note);
  const gmailWebhookUrl = env.GMAIL_WEBHOOK_URL || env.GAS_EMAIL_URL;
  if (gmailWebhookUrl) {
    return sendScholarshipEmailViaGas(gmailWebhookUrl, {
      to,
      subject,
      body: text,
      htmlBody: text.split("\n").map(line => line ? `<p>${escapeEmailHtml(line)}</p>` : "<br>").join(""),
      status,
      note: note || "",
      appId: application.app_id || "",
      studentName: application.student_name || "",
      employeeName: application.employee_name || "",
    });
  }

  const apiKey = env.RESEND_API_KEY || env.EMAIL_API_KEY;
  if (!apiKey) return { sent: false, reason: "RESEND_API_KEY not configured" };
  const from = env.EMAIL_FROM || "Sakura Scholarship <onboarding@resend.dev>";
  const html = text.split("\n").map(line => line ? `<p>${escapeEmailHtml(line)}</p>` : "<br>").join("");

  try {
    const response = await fetch("https://api.resend.com/emails", {
      method: "POST",
      headers: {
        "Authorization": "Bearer " + apiKey,
        "Content-Type": "application/json"
      },
      body: JSON.stringify({ from, to, subject, text, html })
    });
    if (!response.ok) {
      const body = await response.text();
      return { sent: false, reason: "mail api " + response.status + " " + body.slice(0, 120) };
    }
    return { sent: true };
  } catch (err) {
    return { sent: false, reason: err.message || String(err) };
  }
}

async function sendScholarshipEmailViaGas(url, payload) {
  try {
    const response = await fetch(url, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload),
      redirect: "follow"
    });
    const text = await response.text();
    let json = null;
    try { json = text ? JSON.parse(text) : null; } catch (err) {}
    if (!response.ok) return { sent: false, reason: "gas http " + response.status + " " + text.slice(0, 120) };
    if (json && json.success === false) return { sent: false, reason: json.message || "gas send failed" };
    return { sent: true };
  } catch (err) {
    return { sent: false, reason: err.message || String(err) };
  }
}

function scholarshipEmailSubject(status, application) {
  const student = application.student_name || "申請人";
  if (status === "需要補件") return "櫻花教育獎學金補件通知 - " + student;
  if (status === "條件不符") return "櫻花教育獎學金審查結果通知 - " + student;
  if (status === "獲得獎學金") return "恭喜獲得櫻花教育獎學金 - " + student;
  return "櫻花教育獎學金審查進度通知 - " + student;
}

function scholarshipEmailText(status, application, note) {
  const student = application.student_name || "同學";
  const appId = application.app_id || "";
  const reason = note ? "\n\n說明：\n" + note : "";
  if (status === "需要補件") {
    return `親愛的申請人您好：\n\n${student} 的櫻花教育獎學金申請（編號：${appId}）目前需要補件。請依照下方說明補齊資料後，再回到系統重新送出。${reason}\n\n櫻花教育獎學金審查小組`;
  }
  if (status === "條件不符") {
    return `親愛的申請人您好：\n\n${student} 的櫻花教育獎學金申請（編號：${appId}）經審查後，結果為條件不符。${reason}\n\n感謝您對櫻花教育獎學金的支持。\n\n櫻花教育獎學金審查小組`;
  }
  if (status === "獲得獎學金") {
    return `親愛的申請人您好：\n\n恭喜 ${student} 獲得櫻花教育獎學金！申請編號：${appId}。後續領獎或撥款相關資訊，將由承辦單位另行通知。${reason}\n\n櫻花教育獎學金審查小組`;
  }
  return `親愛的申請人您好：\n\n${student} 的櫻花教育獎學金申請（編號：${appId}）目前狀態已更新為：${status}。${reason}\n\n櫻花教育獎學金審查小組`;
}

function escapeEmailHtml(value) {
  return String(value || "").replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
}

