async function reviewerRegister(data, db) {
  const lineUserId = String(data.lineUserId || data.line_user_id || "").trim();
  if (!lineUserId) return { success: false, message: "Missing LINE UID." };

  const displayName = String(data.displayName || data.display_name || "LINE reviewer").trim();
  const requestedUnit = String(data.businessUnit || data.business_unit || "").trim();
  const requestedRole = String(data.requestedRole || data.requested_role || "prelim").trim();
  const username = String(data.username || ("line_" + lineUserId.slice(-12))).replace(/[^\w.-]/g, "_");

  const existing = await db.prepare(`
    SELECT id, username, display_name, role, business_units, active, login_method, line_user_id
    FROM admin_users
    WHERE line_user_id = ?
    ORDER BY id DESC
    LIMIT 1
  `).bind(lineUserId).first();

  if (existing) {
    if (!existing.active) {
      await db.prepare(`
        UPDATE admin_users
        SET display_name = ?, business_units = ?, role = ?, login_method = 'line', updated_at = datetime('now')
        WHERE id = ?
      `).bind(displayName, requestedUnit, requestedRole === "final" ? "final" : "prelim", existing.id).run();
    }
    return {
      success: true,
      message: existing.active ? "已註冊且已啟用，可直接進入審查後台。" : "已收到申請，請等待管理員指派權限。",
      data: {
        id: existing.id,
        username: existing.username,
        displayName: existing.display_name || displayName,
        active: existing.active,
        lineUserId
      }
    };
  }

  await db.prepare(`
    INSERT INTO admin_users (username, password, display_name, role, business_units, active, login_method, line_user_id)
    VALUES (?, ?, ?, ?, ?, 0, 'line', ?)
  `).bind(username, crypto.randomUUID(), displayName, requestedRole === "final" ? "final" : "prelim", requestedUnit, lineUserId).run();

  const created = await db.prepare("SELECT id FROM admin_users WHERE line_user_id = ? ORDER BY id DESC LIMIT 1").bind(lineUserId).first();
  return {
    success: true,
    message: "已收到申請，請等待管理員指派權限。",
    data: {
      id: created?.id || "",
      username,
      displayName,
      active: 0,
      lineUserId
    }
  };
}

function mapWhitelistRoleToAdminUserRole(value) {
  const role = normalizeAdminWhitelistRole(value);
  if (role === "admin") return "admin";
  if (role === "viewer") return "viewer";
  return "final";
}

async function ensureAdminUserFromUidWhitelist(db, whitelistRow) {
  const lineUserId = String(whitelistRow?.line_user_id || "").trim();
  if (!lineUserId) return null;

  const displayName = String(whitelistRow.display_name || "").trim() || "LINE 管理員";
  const role = mapWhitelistRoleToAdminUserRole(whitelistRow.role);
  const businessUnits = normalizeAdminAllowedModules(whitelistRow.allowed_modules || "*");
  const username = ("line_admin_" + lineUserId).replace(/[^\w.-]/g, "_");

  const existing = await db.prepare(`
    SELECT id, username, display_name, role, business_units, active, login_method, line_user_id
    FROM admin_users
    WHERE line_user_id = ?
    ORDER BY id DESC
    LIMIT 1
  `).bind(lineUserId).first();

  if (existing) {
    await db.prepare(`
      UPDATE admin_users
      SET display_name = ?,
          role = ?,
          business_units = ?,
          active = 1,
          login_method = CASE
            WHEN login_method = 'password' THEN 'both'
            WHEN login_method IS NULL OR login_method = '' THEN 'line'
            ELSE login_method
          END,
          updated_at = datetime('now')
      WHERE id = ?
    `).bind(displayName, role, businessUnits, existing.id).run();

    return await db.prepare(`
      SELECT id, username, display_name, role, business_units, active, login_method, line_user_id
      FROM admin_users
      WHERE id = ?
    `).bind(existing.id).first();
  }

  await db.prepare(`
    INSERT INTO admin_users (username, password, display_name, role, business_units, active, login_method, line_user_id)
    VALUES (?, ?, ?, ?, ?, 1, 'line', ?)
  `).bind(username, crypto.randomUUID(), displayName, role, businessUnits, lineUserId).run();

  return await db.prepare(`
    SELECT id, username, display_name, role, business_units, active, login_method, line_user_id
    FROM admin_users
    WHERE line_user_id = ?
    ORDER BY id DESC
    LIMIT 1
  `).bind(lineUserId).first();
}
async function reviewerLineLogin(data, db, request) {
  const lineUserId = String(data.lineUserId || data.line_user_id || "").trim();
  if (!lineUserId) return { success: false, message: "Missing LINE UID." };

  
  await ensureAdminUidWhitelistTable(db);
  const whitelistRow = await db.prepare(`
    SELECT id, line_user_id, display_name, role, allowed_modules, active
    FROM admin_uid_whitelist
    WHERE line_user_id = ? AND active = 1
    LIMIT 1
  `).bind(lineUserId).first();

  if (whitelistRow) {
    const whitelistUser = await ensureAdminUserFromUidWhitelist(db, whitelistRow);
    if (!whitelistUser) return { success: false, message: "UID 白名單帳號建立失敗。" };
    const session = await createAdminSession(db, whitelistUser, request, "uid_whitelist_line_login");
    return {
      success: true,
      message: "Login successful.",
      data: {
        ...session,
        allowedModules: normalizeAdminAllowedModules(whitelistRow.allowed_modules || "*")
      }
    };
  }
const user = await db.prepare(`
    SELECT id, username, display_name, role, business_units, active, login_method, line_user_id
    FROM admin_users
    WHERE line_user_id = ? AND active = 1 AND login_method IN ('line', 'both')
    ORDER BY id DESC
    LIMIT 1
  `).bind(lineUserId).first();

  if (!user) {
    const pending = await db.prepare(`
      SELECT id, username, display_name, active
      FROM admin_users
      WHERE line_user_id = ?
      ORDER BY id DESC
      LIMIT 1
    `).bind(lineUserId).first();
    return {
      success: false,
      pending: Boolean(pending),
      message: pending ? "帳號尚未啟用，請等待管理員指定權限。" : "尚未註冊審查權限。"
    };
  }

  const session = await createAdminSession(db, user, request, "line_login");
  return {
    success: true,
    message: "Login successful.",
    data: session
  };
}

async function getPermissionConfig(data, db, env) {
  const auth = await requireAdmin(data, db);
  if (!auth.ok) return auth.response;
  if (auth.user.role !== "admin") return { success: false, message: "Admin only." };

  const usersResult = await db.prepare(`
    SELECT id, username, display_name, role, business_units, active, login_method, line_user_id
    FROM admin_users
    ORDER BY active DESC, username ASC
  `).all();
  const permsResult = await db.prepare(`
    SELECT p.user_id, p.business_unit, p.review_stage
    FROM admin_user_permissions p
    JOIN admin_users u ON u.id = p.user_id
    WHERE p.active = 1
    ORDER BY p.user_id, p.business_unit, p.review_stage
  `).all();
  await logAdminActivity(db, auth.user, "view_permission_config", { detail: "查看權限設定" });

  return {
    success: true,
    data: {
      users: usersResult.results || [],
      permissions: permsResult.results || [],
      businessUnits: DEFAULT_BUSINESS_UNITS
    }
  };
}

async function savePermissionUser(data, db, env) {
  const auth = await requireAdmin(data, db);
  if (!auth.ok) return auth.response;
  if (auth.user.role !== "admin") return { success: false, message: "Admin only." };

  const username = String(data.username || "").trim();
  if (!username) return { success: false, message: "Username is required." };

  const id = Number(data.id || 0);
  const displayName = String(data.displayName || data.display_name || username).trim();
  const loginMethod = String(data.loginMethod || data.login_method || "password").trim() || "password";
  const lineUserId = String(data.lineUserId || data.line_user_id || "").trim();
  const active = data.active === false || data.active === 0 || data.active === "0" ? 0 : 1;
  const isAdminUser = Boolean(data.isAdmin || data.role === "admin");
  const permissions = Array.isArray(data.permissions) ? data.permissions : [];
  const passwordValue = String(data.password || "");
  if (!id && loginMethod === "line" && !lineUserId) {
    return { success: false, message: "LINE 審查人員請使用邀約網址註冊，系統會自動取得 LINE UID 後再由管理員核准。" };
  }
  if (loginMethod === "line" && !lineUserId) {
    return { success: false, message: "此帳號尚未綁定 LINE UID，請先請對方使用邀約網址完成註冊。" };
  }
  if (!id && loginMethod !== "line" && !passwordValue.trim()) {
    return { success: false, message: "新增帳密登入帳號請設定密碼；LINE 人員請改用邀約註冊流程。" };
  }
  const permissionUnits = Array.from(new Set(permissions.map(p => p.businessUnit).filter(Boolean)));
  const role = isAdminUser ? "admin" : deriveRoleFromPermissions(permissions);
  const businessUnits = isAdminUser ? "*" : (permissionUnits.includes("*") ? "*" : permissionUnits.join(","));

  let userId = id;
  if (userId) {
    const existing = await db.prepare("SELECT id FROM admin_users WHERE id = ?").bind(userId).first();
    if (!existing) return { success: false, message: "User not found." };
    if (data.password) {
      await db.prepare(`
        UPDATE admin_users
        SET username = ?, password = ?, display_name = ?, role = ?, business_units = ?, active = ?, login_method = ?, line_user_id = ?, updated_at = datetime('now')
        WHERE id = ?
      `).bind(username, String(data.password), displayName, role, businessUnits, active, loginMethod, lineUserId, userId).run();
    } else {
      await db.prepare(`
        UPDATE admin_users
        SET username = ?, display_name = ?, role = ?, business_units = ?, active = ?, login_method = ?, line_user_id = ?, updated_at = datetime('now')
        WHERE id = ?
      `).bind(username, displayName, role, businessUnits, active, loginMethod, lineUserId, userId).run();
    }
  } else {
    await db.prepare(`
      INSERT INTO admin_users (username, password, display_name, role, business_units, active, login_method, line_user_id)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?)
    `).bind(username, passwordValue || "@1234", displayName, role, businessUnits, active, loginMethod, lineUserId).run();
    const created = await db.prepare("SELECT id FROM admin_users WHERE username = ?").bind(username).first();
    userId = created.id;
  }

  await db.prepare("UPDATE admin_user_permissions SET active = 0, updated_at = datetime('now') WHERE user_id = ?").bind(userId).run();
  for (const perm of permissions) {
    const unit = String(perm.businessUnit || "").trim();
    const stage = String(perm.stage || "").trim();
    if (!unit || !["prelim", "final"].includes(stage)) continue;
    await db.prepare(`
      INSERT INTO admin_user_permissions (user_id, business_unit, review_stage, active, updated_at)
      VALUES (?, ?, ?, 1, datetime('now'))
      ON CONFLICT(user_id, business_unit, review_stage)
      DO UPDATE SET active = 1, updated_at = datetime('now')
    `).bind(userId, unit, stage).run();
  }

  await logAdminActivity(db, auth.user, "save_permission_user", {
    detail: "儲存權限帳號：" + username
  });
  return { success: true, message: "Saved.", data: { id: userId } };
}

function deriveRoleFromPermissions(permissions) {
  const stages = new Set((permissions || []).map(p => p.stage));
  if (stages.has("prelim") && stages.has("final")) return "reviewer";
  if (stages.has("final")) return "final";
  return "prelim";
}

async function findReviewers(db, businessUnit) {
  const row = await db.prepare("SELECT prelim_reviewer, final_reviewer FROM reviewers WHERE business_unit = ?")
    .bind(businessUnit || "")
    .first();
  return {
    prelimReviewer: row?.prelim_reviewer || "",
    finalReviewer: row?.final_reviewer || "",
  };
}

async function nextApplicationId(db) {
  const row = await db.prepare("SELECT COUNT(*) AS count FROM applications").first();
  const serial = Number(row?.count || 0) + 1;
  return "SAKURA-" + new Date().getFullYear() + "-" + String(serial).padStart(5, "0");
}

async function logAction(db, appId, action, oldStatus, newStatus, note) {
  await db.prepare("INSERT INTO audit_logs (app_id, action, old_status, new_status, note) VALUES (?, ?, ?, ?, ?)")
    .bind(appId || "", action || "", oldStatus || "", newStatus || "", note || "")
    .run();
}

async function logAdminActivity(db, user, action, options = {}) {
  const request = options.request;
  const ip = request ? (request.headers.get("cf-connecting-ip") || request.headers.get("x-forwarded-for") || "") : "";
  const userAgent = request ? (request.headers.get("user-agent") || "") : "";
  try {
    await db.prepare(`
      INSERT INTO admin_activity_logs
        (username, display_name, role, action, target_app_id, target_row_id, detail, ip, user_agent)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
    `).bind(
      user?.username || "",
      user?.display_name || user?.displayName || user?.username || "",
      user?.role || "",
      action || "",
      options.targetAppId || "",
      options.targetRowId || null,
      options.detail || "",
      ip,
      userAgent
    ).run();
  } catch (err) {
    console.warn("admin activity log skipped", err.message);
  }
}

function toClientObject(row) {
  const formName = (row.application_year || "2026") + " Scholarship Application";
  const titleYear = toWesternYear(row.created_at) || new Date().getFullYear();
  const title = formName + " (" + titleYear + ")";
  const result = resultFromStatus(row.status);
  const closedAt = closedDateFromStatus(row.status, row.updated_at);
  const applicantDisplay = [row.business_unit, row.employee_dept, row.employee_name].filter(Boolean).join(" ");
  return {
    rowIndex: row.id,
    appId: row.app_id,
    formNo: row.app_id,
    formName,
    title,
    applicant: applicantDisplay || row.applicant_name || row.employee_name,
    result,
    applyDate: row.created_at,
    closedAt,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
    applicationYear: row.application_year,
    academicYear: row.academic_year,
    group: row.group_name,
    studentName: row.student_name,
    gender: row.gender,
    school: row.school,
    grade: row.grade,
    department: row.department,
    age: row.age,
    intellectTop: row.intellect_top,
    intellectBottom: row.intellect_bottom,
    moralTop: row.moral_top,
    moralBottom: row.moral_bottom,
    talentOrganizer: row.talent_organizer,
    talentCategory: row.talent_category,
    talentResult: row.talent_result,
    messageToSakura: row.message_to_sakura,
    employeeName: row.employee_name,
    relationship: row.relationship,
    applicantName: row.applicant_name,
    businessUnit: row.business_unit,
    employeeDept: row.employee_dept,
    employeeId: row.employee_id,
    phone: row.phone,
    email: row.email,
    address: row.address,
    applicantConfirm: row.applicant_confirm,
    confirmDate: row.confirm_date,
    agreeTerms: row.agree_terms ? "yes" : "no",
    photoUrl: row.photo_url,
    transcriptUrl: row.transcript_url,
    transcriptUrlsJson: row.transcript_urls_json,
    prelimStatus: row.prelim_status,
    finalStatus: row.final_status,
    status: row.status,
    supplementNote: row.supplement_note,
    prelimReviewer: row.prelim_reviewer,
    finalReviewer: row.final_reviewer
  };
}
function toWesternYear(value) {
  if (!value) return "";
  const year = new Date(value).getFullYear();
  return Number.isFinite(year) ? year : "";
}

function resultFromStatus(status) {
  if (status === "approved" || status === "缺件??" || status === "??") return "approved";
  if (status === "??") return "rejected";
  if (status === "deleted") return "deleted";
  if (status === "??" || status === "submitted") return "supplement";
  return status || "pending";
}

function closedDateFromStatus(status, updatedAt) {
  if (["approved", "缺件??", "??", "??", "deleted"].includes(status)) return updatedAt || "";
  return "";
}

const reviewerRegisterHtml = `<!DOCTYPE html>
<html lang="zh-TW">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>審查人員註冊</title>
  <script src="https://cdn.tailwindcss.com"></script>
  <script src="https://static.line-scdn.net/liff/edge/2/sdk.js"></script>
</head>
<body class="bg-slate-50 text-slate-900 min-h-screen">
  <main class="max-w-xl mx-auto p-5">
    <section class="bg-white rounded-xl shadow-sm border-t-4 border-rose-600 p-6 mt-8">
      <h1 class="text-2xl font-black mb-2">審查人員權限註冊</h1>
      <p class="text-slate-500 mb-5">請使用福委會 LINE Login 進入，系統會抓取 UID。送出後由管理員在 Permissions 指定單位、初審與複審權限。</p>
      <div id="status" class="rounded-lg bg-slate-100 p-4 text-sm leading-7 mb-5">準備讀取 LINE 身份...</div>
      <form id="registerForm" class="space-y-4 hidden">
        <div>
          <label class="font-bold">LINE UID</label>
          <input id="lineUserId" class="w-full border rounded-lg p-3 bg-slate-50" readonly>
        </div>
        <div>
          <label class="font-bold">姓名</label>
          <input id="displayName" class="w-full border rounded-lg p-3" required>
        </div>
        <div>
          <label class="font-bold">申請單位</label>
          <select id="businessUnit" class="w-full border rounded-lg p-3"></select>
        </div>
        <div>
          <label class="font-bold">申請角色</label>
          <select id="requestedRole" class="w-full border rounded-lg p-3">
            <option value="prelim">初審</option>
            <option value="final">複審</option>
            <option value="reviewer">初審 + 複審</option>
          </select>
        </div>
        <button class="w-full bg-rose-600 text-white rounded-lg py-3 font-black" type="submit">送出權限申請</button>
      </form>
      <button id="enterAdminBtn" class="hidden w-full bg-slate-900 text-white rounded-lg py-3 font-black mt-4" type="button">進入審查後台</button>
    </section>
  </main>
  <script>
    const LIFF_ID = "__SAKURA_LIFF_ID__";
    const BUSINESS_UNITS = ["總管理處","製造管理處","營業管理處","服務管理處","品牌/產品管理處","海外事業處","廚電事業處","廚櫃事業處","櫻花家居","雅適","櫻中","櫻順","越南子公司台幹","櫻花總經銷","廚藝生活館","太陽能總代理","其他"];
    const statusBox = document.getElementById("status");
    const form = document.getElementById("registerForm");
    const enterAdminBtn = document.getElementById("enterAdminBtn");
    let profile = null;

    function liffRedirectUri(){
      return location.origin + "/?liff.state=" + encodeURIComponent(location.pathname + location.search);
    }

    function setStatus(text, isError) {
      statusBox.className = "rounded-lg p-4 text-sm leading-7 mb-5 " + (isError ? "bg-red-50 text-red-700" : "bg-slate-100 text-slate-700");
      statusBox.textContent = text;
    }
    function esc(v) {
      return String(v == null ? "" : v).replace(/[&<>"']/g, function(c) {
        return {"&":"&amp;","<":"&lt;",">":"&gt;","\\"":"&quot;","'":"&#39;"}[c];
      });
    }
    async function api(action, data) {
      const res = await fetch("/api", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ action: action, data: data || {} })
      });
      return res.json();
    }
    async function init() {
      document.getElementById("businessUnit").innerHTML = BUSINESS_UNITS.map(function(unit) {
        return "<option>" + esc(unit) + "</option>";
      }).join("");

      try {
        if (!window.liff || !LIFF_ID) throw new Error("LIFF 尚未設定。");
        await liff.init({ liffId: LIFF_ID });
        if (!liff.isLoggedIn()) {
          liff.login({ redirectUri: liffRedirectUri() });
          return;
        }
        profile = await liff.getProfile();
        document.getElementById("lineUserId").value = profile.userId || "";
        document.getElementById("displayName").value = profile.displayName || "";
        setStatus("已取得 LINE UID：" + profile.userId);
        form.classList.remove("hidden");

        const login = await api("reviewerLineLogin", { lineUserId: profile.userId });
        if (login.success && login.data && login.data.token) {
          localStorage.setItem("sakura_admin_session", JSON.stringify(login.data));
          setStatus("此 UID 已啟用權限，可以直接進入審查後台。");
          enterAdminBtn.classList.remove("hidden");
        } else if (login.pending) {
          setStatus(login.message || "帳號尚未啟用，請等待管理員指定權限。");
        }
      } catch (err) {
        setStatus(err.message || String(err), true);
      }
    }
    form.addEventListener("submit", async function(event) {
      event.preventDefault();
      if (!profile || !profile.userId) return setStatus("尚未取得 LINE UID。", true);
      setStatus("送出中...");
      const res = await api("reviewerRegister", {
        lineUserId: profile.userId,
        displayName: document.getElementById("displayName").value,
        businessUnit: document.getElementById("businessUnit").value,
        requestedRole: document.getElementById("requestedRole").value
      });
      if (!res.success) return setStatus(res.message || "送出失敗", true);
      setStatus(res.message || "已送出，請等待管理員指定權限。");
    });
    enterAdminBtn.addEventListener("click", function() {
      location.href = "/scholarship";
    });
    init();
  </script>
</body>
</html>`;

